-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირიდან, როცა ორსულობის 7-ე თვეში ხართ, მშობიარობამდე თქვენი ბავშვი დაახლოებით იმდენივე წონას მოიმატებს, რამდენსაც ახლა იწონის. ამის მთავარი მიზეზია თეთრი ცხიმოვანი უჯრედები, რომლებსაც მისი სხეული ყავისფერ ცხიმთან ერთად წარმოქმნის. თეთრი ცხიმოვანი ქსოვილი ჭარბ ენერგიას ცხიმოვან უჯრედებში ტრიგლიცერიდების სახით ინახავს და საჭიროების შემთხვევაში შეუძლია სწრაფად დააბრუნოს ის სისხლის მიმოქცევის სისტემაში. ცხიმოვანი ქსოვილი ორგანიზმში ენერგიის უდიდესი საცავია; ის ჰორმონული სიგნალების საშუალებით მართავს ცხიმოვან უჯრედებში ენერგიის შენახვასა და გამოთავისუფლებას. ცხიმოვანი ქსოვილი შედგება ცხიმოვანი უჯრედებისგან და შეიცავს სისხლძარღვებისა და ნერვების მდიდარ ქსელს. ის მამაკაცებში სხეულის წონის 15-20%-ს, ქალებში კი 20-25%-ს შეადგენს. ცხიმოვანი უჯრედები ნეიტრალური ცხიმების შესანახად და სითბოს წარმოსაქმნელად სპეციალიზებული უჯრედებია. ვინაიდან ადამიანის ორგანიზმში საკვების მიღება პერიოდულია, ხოლო ენერგიის ხარჯვა — უწყვეტი, ეს უჯრედები ენერგიის საცავის მნიშვნელოვან ფუნქციას ასრულებს. ცხიმოვანი ქსოვილი სხეულს ტრავმებისგან იცავს და მის თბოიზოლაციაში აქტიურ როლს ასრულებს. ამასთანავე, ის ძალიან მგრძნობიარეა ნერვული და ჰორმონული სტიმულების მიმართ.'), baby_message_ka = COALESCE(baby_message_ka, '29 კვირა! 🎃 მე დიდი გოგრის ზომის ვარ! ყოველდღე სულ უფრო მეტად ვემსგავსები "ადამიანს". ჩემი თავი სხეულის პროპორციულია. ახლა ჩემი მთავარი მიზანი წონის მომატებაა. როცა გირტყამ, ჩემს ძალას უკვე უკეთ გრძნობ, ხომ ასეა?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'კანს ელასტიკური სტრუქტურა აქვს. ორსულობის პერიოდში მზარდი მუცელი და მკერდი კანის დამატებით დაჭიმვას იწვევს. ამ დაჭიმვის შედეგად კანი ტენიანობას კარგავს და ქავილი ჩნდება. ქავილი შესაძლოა დაიწყოს იმ კვირებიდან, როცა მუცელი უკვე შესამჩნევი ხდება. ამასთანავე, მკერდისა და მუცლის მიდამოში გაჩენილმა სტრიებმაც შეიძლება დროდადრო ქავილი გამოიწვიოს. კანის დაჭიმვითა და ტენიანობის დაკარგვით გამოწვეული ქავილის დროს შეგიძლიათ ქავილის მქონე ადგილები ექიმის მიერ რეკომენდებული დამატენიანებელი კრემით ან ვაზელინით დაიტენიანოთ. ქავილის შემცირებაში შეიძლება ისეთი ზეთებიც დაგეხმაროთ, როგორიცაა ნუშის ზეთი. ორსულობის დროს არ უნდა გამოიყენოთ სუნამო ან სურნელოვანი კოსმეტიკური საშუალებები, რადგან მათ ქავილის კიდევ უფრო გაძლიერება შეუძლიათ. ორგანიზმში ტენიანობის ბალანსის შესანარჩუნებლად ბევრი წყალი უნდა დალიოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღის განმავლობაში საკვები 5-6 მცირე ულუფად გადაანაწილეთ. დიდი ულუფები გულძმარვას აძლიერებს. ჭამის დასრულებისთანავე ნუ დაწვებით — გამართულად იდექით ან გაისეირნეთ.') WHERE id = 'cad83eb0-58a7-4d1b-bb76-60f58c14c58f';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'შეხება პირველი და ყველაზე განვითარებული გრძნობაა, რომელსაც თქვენი ბავშვი სამყაროს შესაცნობად იყენებს. ამჟამად ის საშვილოსნოში ნამდვილი მკვლევარივით იქცევა: ხელებით ეხება საშვილოსნოს კედლებს, იჭერს ჭიპლარს, წოვს თითებს და ხშირად სახეზე ისვამს ხელს.;;;
ეს შეხებები მხოლოდ მოძრაობები კი არა, ტვინის სენსორული განვითარებისთვის მნიშვნელოვანი სიგნალებიცაა. საინტერესოა, რომ ამ ეტაპზე თქვენი ბავშვის თირკმელზედა ჯირკვლებიც მეტად მნიშვნელოვან ფუნქციას ასრულებს. ისინი იწყებს სპეციალური ჰორმონის — კორტიზოლის — გამოყოფას. კორტიზოლი თქვენი ბავშვის ფილტვების მომწიფებისთვის „ჯადოსნური გასაღების“ როლს ასრულებს. ის ფილტვის ქსოვილებში აჩქარებს ნივთიერება სურფაქტანტის გამომუშავებას. სურფაქტანტი კი ხელს უშლის ფილტვებში არსებული პატარა ჰაერის პარკუჭების ერთმანეთთან შეწებებას. ამ პროცესის წყალობით, დაბადებისთანავე თქვენი ბავშვი ადვილად შეძლებს პირველი ჩასუნთქვის გაკეთებას და მისი ფილტვები სრულად აივსება ჰაერით. ამგვარად, როგორც ფიზიკური მოძრაობები, ისე შინაგანი ჰორმონები თქვენს ბავშვს შესანიშნავად ამზადებს დიდი „გახსნის დღისთვის“ — პირველი ჩასუნთქვისა და პირველი შეხებისთვის.'), baby_message_ka = COALESCE(baby_message_ka, 'მე შენ გრძნობ! 🤗 დედიკო, როცა მუცელზე ხელს მისვამ ან მამა ხელს გადებს, მე ამ სითბოსა და ზეწოლას ვგრძნობ. ზოგჯერ მეც შიგნიდან იმავე ადგილს ვეხები. ეს ჩვენი „მისალმებაა“. ჩვენ შორის მხოლოდ თხელი კედელია, ჩვენი სულები კი ერთია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'გულმავიწყობამ შესაძლოა პიკს მიაღწიოს. შეიძლება ყურადღების მოკრებაც გაგიჭირდეთ. სრულიად ნორმალურია, თუ გასაღებებს მაცივარში იპოვით ან წინადადების შუაში დაგავიწყდებათ, რის თქმას აპირებდით. თქვენი ტვინი „დედობის რეჟიმზე“ გადადის და პრიორიტეტებს ცვლის.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ პერიოდში შესაძლოა უძილობა გაწუხებდეთ, ამიტომ დღის განმავლობაში ეცადეთ, მცირე შესვენებებით დაისვენოთ. ამ საღამოს თქვენს ბავშვთან ერთად მშვიდ მუსიკას მოუსმინეთ — ის თქვენს სიმშვიდეს იზიარებს.') WHERE id = '0a286cb7-93f1-451a-b6be-b5b9dd7ce160';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ყოველდღიურად თქვენი ბავშვის ტვინში მილიარდობით ნეირონი განაგრძობს წარმოქმნას. ამ ეტაპზე ნეირონების საერთო რაოდენობამ უკვე რამდენიმე ტრილიონს მიაღწია. თქვენი ბავშვის სხეულში არსებული დაახლოებით 100 ტრილიონი უჯრედიდან დაახლოებით 7% ნერვულ სისტემას შეადგენს. ეს ინფორმაციის გადაცემის სასიცოცხლო მნიშვნელობაზე მიუთითებს. ფუნქციის მიხედვით ნერვული უჯრედები 3 ჯგუფად იყოფა: მგრძნობიარე, მამოძრავებელი და ჩართული ნეირონები. მგრძნობიარე ნეირონებს რეცეპტორებიდან მიღებული იმპულსები ცენტრალური ნერვული სისტემის ორგანოებამდე, მათ შორის თავისა და ზურგის ტვინამდე, მიაქვს. მამოძრავებელ ნეირონებს ცენტრალური ნერვული სისტემიდან მიღებული ბრძანებები კუნთებამდე ან ჯირკვლებამდე გადააქვს. ჩართული ნეირონები კი ცენტრალურ ნერვულ სისტემაში მდებარეობს და მამოძრავებელ და მგრძნობიარე ნეირონებს ერთმანეთთან აკავშირებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ტვინი ნაოჭდება! 🧠 ადრე ჩემი ტვინი გლუვი იყო, ახლა კი ნიგვზის გულივით დანაოჭებული ხდება. რატომ? იმიტომ, რომ ჩემი ტვინის უჯრედები იმდენად სწრაფად მრავლდება, რომ თავის ქალაში ჩასატევად ტვინი უნდა დაიკეცოს. ეს ნაოჭები აჩვენებს, რომ ჩემი გონება, მეხსიერება და უნარები ვითარდება. გენიოსობისთვის ვემზადები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი გოგრა'), body_changes_ka = COALESCE(body_changes_ka, 'ცრუ შეკუმშვები შესაძლოა უფრო ხშირი და შესამჩნევი გახდეს. დღის განმავლობაში თქვენი მუცელი შეიძლება რამდენჯერმე ქვასავით გამაგრდეს. ეს უმტკივნეულოა, თუმცა შესაძლოა დისკომფორტი გამოიწვიოს. თუ შეკუმშვები რეგულარულია (მაგალითად, ყოველ 10 წუთში ერთხელ) და მტკივნეულია, ეს შეიძლება ნაადრევი მშობიარობის ნიშანი იყოს — დაუყოვნებლივ დაუკავშირდით ექიმს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ამ დღეებში შეგიძლიათ ნელ-ნელა დაამატოთ სამშობიარო ჩანთის სიას საჭირო ჰიგიენური საშუალებები. ვახშმად მსუბუქ საკვებს მიანიჭეთ უპირატესობა, რათა უფრო მშვიდად დაიძინოთ.') WHERE id = '195a150b-6bd1-4a69-9196-35f5d6e3f9f4';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კანზე რამდენიმე კვირის წინ წარმოქმნილმა ვერნიქსის შრემ გასქელება დაიწყო. ვერნიქსი კრემის მსგავსი შრეა, რომელიც ორსულობის ბოლო 3 თვის განმავლობაში ბავშვის კანზე წარმოიქმნება. თითქმის ყველა ბავშვი სხეულზე ვერნიქსის შრით იბადება. ნაადრევად დაბადებულ ბავშვებს ვერნიქსის უფრო სქელი შრე აქვთ, ხოლო 40 კვირის შემდეგ დაბადებულ ბავშვებში ის საკმაოდ მცირე რაოდენობით გვხვდება. ვერნიქსად წოდებული ეს ცხიმოვანი შრე თეთრი ფერისაა და კრემის მსგავსი სქელი კონსისტენცია აქვს. ვერნიქსი ცხიმოვანი სეკრეციის სახეობაა, რომელსაც თქვენი ბავშვის კანის ცხიმოვანი უჯრედები თქვენ მიერ გამომუშავებული ჰორმონების სტიმულირების შედეგად გამოყოფს. ვერნიქსი დაახლოებით 50 სპეციალურ ცილას შეიცავს და თქვენს ბავშვს როგორც საშვილოსნოში, ისე დაბადების შემდეგ სხვადასხვა ინფექციისგან საკმაოდ ეფექტურად იცავს. დაბადების შემდეგ, სამყაროსთან შეგუების პროცესშიც, ვერნიქსი ბავშვის კანის დაცვას განაგრძობს. დაბადებიდან 1-2 დღის განმავლობაში ბავშვის კანი ვერნიქსს მთლიანად შეიწოვს. ეს ახალშობილობის პერიოდში გამონაყარის განვითარების ალბათობასაც ამცირებს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემს ბიძგებს ითვლი? 🦶 ექიმები ამბობენ, რომ ჩემს მოძრაობებს უნდა დააკვირდე. ჩვეულებრივ, ჭამის შემდეგ ან როცა ისვენებ, უფრო აქტიური ვარ. თუ დიდხანს გავჩუმდი, ერთი ჭიქა ტკბილი წყალი დალიე და მარცხენა გვერდზე დაწექი. მაშინვე გამოგეხმაურები. ზოგჯერ უბრალოდ ღრმად მძინავს.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'თუ საზარდულის ტკივილი გაწუხებთ, არ უნდა ინერვიულოთ. ბავშვის ზრდა თქვენი სხეულის წონასწორობის ცენტრს ცვლის, რის გამოც სხეულის სხვადასხვა ნაწილში შეიძლება ტკივილი გაჩნდეს. ერთ-ერთი მათგანია საზარდულის არეში ტკივილი. საზარდულის ტკივილი ორსულობის დროს გავრცელებული ჩივილია. ის შეიძლება გამოვლინდეს როგორც მსუბუქი ყრუ ტკივილი, ასევე პერიოდული მწვავე ტკივილი.;;;
ორსულობის პირველ ტრიმესტრში საზარდულის ტკივილი საშვილოსნოს ზრდას უკავშირდება, ხოლო ბოლო ტრიმესტრში — სხეულის მშობიარობისთვის მომზადებას. გარდა ამისა, ორგანიზმში მაგნიუმის არასაკმარისი რაოდენობისას ეს ტკივილი შესაძლოა გახშირდეს და გაძლიერდეს. ავოკადო, თხილი, პარკოსნები, სრულმარცვლოვანი პროდუქტები, ცხიმიანი თევზი და ბანანი დიდი რაოდენობით მაგნიუმს შეიცავს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხების შეშუპებისა და სიმძიმის შესამცირებლად ჩაიცვით კომფორტული ფეხსაცმელი, ხოლო ჯდომისას ფეხები მაღლა შემოაწყვეთ. დღის განმავლობაში განაგრძეთ ბავშვის მოძრაობებზე დაკვირვება; ჩვეულებრივ, 2 საათის განმავლობაში 10 მოძრაობის შეგრძნება ნორმად ითვლება. ამ საღამოს საკუთარ თავს ცოტა დრო დაუთმეთ, თბილი შხაპი მიიღეთ და თქვენს ბავშვთან ერთად მომავალ ლამაზ დღეებზე იოცნებეთ.') WHERE id = 'eadf5bb2-e6e7-4d41-83d0-6c1c3223ad40';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თუ თქვენი ბავშვი გოგოა, მისი საკვერცხეები განვითარებასა და მილიონობით კვერცხუჯრედის ჩამოყალიბებას განაგრძობს. საკვერცხე ეწოდება ორ სიმეტრიულ ჯირკვალს, რომლებიც საშვილოსნოს ორივე მხარეს მდებარეობს და ფართო იოგებითაა გარშემორტყმული. საკვერცხე ქალის რეპროდუქციული ორგანოა, რომელშიც ქალის სასქესო უჯრედები — კვერცხუჯრედები ინახება. თქვენი ბავშვის თითოეულ საკვერცხეში მრავალი ფოლიკულია, რომლებიც მომავალში კვერცხუჯრედების მომწიფებაში მიიღებს მონაწილეობას. ეს კვერცხუჯრედები ჯერ ჩანასახოვან მდგომარეობაშია და სქესობრივი მომწიფების პერიოდამდე არ მწიფდება. სქესობრივი მომწიფების შემდეგ, ჰიპოფიზის მიერ გამოყოფილი ჰორმონების ზემოქმედებით, ყოველთვიურად ერთი კვერცხუჯრედი მწიფდება და საშვილოსნოსკენ გადაადგილდება. ამ ჰორმონებს მიეკუთვნება: FSH, რომელიც კვერცხუჯრედის მომწიფებას უზრუნველყოფს; LH, რომელიც ოვულაციას იწვევს; ფოლიკულებიდან გამოყოფილი ესტროგენი, რომელიც მეორეული სასქესო ნიშნების ჩამოყალიბებას უწყობს ხელს; და ყვითელი სხეულის მიერ გამოყოფილი პროგესტერონი, რომელიც საშვილოსნოს შიდა გარსს ორსულობისთვის ამზადებს. თუ მომწიფებული კვერცხუჯრედი სპერმატოზოიდით არ განაყოფიერდება, ის ორგანიზმიდან გამოიდევნება და მენსტრუაცია იწყება.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ერთი დიდი კომბოსტოს ზომის ვარ! დედიკო, დაუჯერებელია — გზის 3/4 (75%) უკვე გავიარეთ! სულ რაღაც 10 კვირა დაგვრჩა (დაახლოებით). მე უკვე დიდი ბავშვი ვარ, უბრალოდ ჩემს ფილტვებსა და ტვინს ჯერ კიდევ სჭირდება სრულად მომწიფება. ფინიშამდე სულ ცოტა დარჩა!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ექიმთან გამოკვლევების დროულად ჩატარება ძალიან მნიშვნელოვანია ისეთი პრობლემების ადრეული დიაგნოსტიკისთვის, როგორიცაა სანაყოფე წყლების შემცირება. ორსულობის დროს სანაყოფე წყლების შემცირება ულტრაბგერითი გამოკვლევით ჩატარებული გაზომვების საფუძველზე დგინდება. სანაყოფე წყლების შემცირებად მიიჩნევა მდგომარეობა, როდესაც სითხის საერთო მოცულობა 500 ml-ზე ნაკლებია. პლაცენტაში სისხლის მიმოქცევის შენელებამ შესაძლოა სანაყოფე წყლების შემცირებას შეუწყოს ხელი. სისხლძარღვების შევიწროებით გამოწვეული ჰიპერტენზიის ან სისხლნაკლებობის დროს ბავშვისთვის მიწოდებული სისხლის რაოდენობა მცირდება. ამან კი, თავის მხრივ, შესაძლოა სანაყოფე წყლების შემცირება გამოიწვიოს.;;;
გარდა ამისა, ორგანიზმში სითხის საერთო ნაკლებობა და ზოგიერთ შემთხვევაში შაქრიანი დიაბეტიც შეიძლება ორსულობისას სანაყოფე წყლების შემცირების მიზეზი გახდეს. სანაყოფე წყლების რაოდენობა შეიძლება შემცირდეს ექიმის დანიშნულების გარეშე მიღებული ზოგიერთი მედიკამენტის გვერდითი ეფექტის გამოც. ამ პრობლემის განვითარების ალბათობა ასევე იზრდება 42 კვირისა და უფრო ხანგრძლივი ორსულობის დროს.'), daily_tip_ka = COALESCE(daily_tip_ka, '30-ე კვირის დასრულება მშვიდი დასვენებით აღნიშნეთ. წელის ტკივილის შესამცირებლად ჯდომისას აუცილებლად გამოიყენეთ ბალიშები, რომლებიც ზურგს სათანადოდ გიჭერთ. თუ ჯერ არ დაგიწყიათ, შეგიძლიათ ბავშვის ჩანთისთვის აუცილებელი ნივთების (საფენების, ტანსაცმლის) მომზადებას შეუდგეთ. ხვალიდან 31-ე კვირას — მშობიარობამდე დარჩენილ ბოლო დიდ მონაკვეთს ვიწყებთ!') WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის თვალის ფერად ნაწილში — ირისში — პიგმენტაცია გრძელდება. ირისი თვალის გუგის ზომასა და თვალში შემავალი სინათლის რაოდენობას აკონტროლებს. მიუხედავად იმისა, რომ თვალის მრავალი განსხვავებული ფერი არსებობს, ირისის ფერზე პასუხისმგებელი მხოლოდ ერთი ტიპის პიგმენტია. თუ ირისის წინა შრეში პიგმენტი ბევრია, თქვენი ბავშვის თვალები ყავისფერი იქნება; თუ პიგმენტი ცოტაა — მწვანე, ხოლო თუ ძალიან მცირეა ან თითქმის არ არის — ლურჯი. თქვენი ბავშვის თვალის ფერი განაყოფიერების პირველივე მომენტიდან გენეტიკურად არის განსაზღვრული. ეს პიგმენტაცია ორსულობის მე-4 კვირიდან იწყებს ჩამოყალიბებას. მიუხედავად იმისა, რომ პიგმენტის წარმოქმნა ძალიან ადრეულ ეტაპზე იწყება, ბავშვის თვალის ფერის გასაგებად მის დაბადებას უნდა დაელოდოთ. მართალია, ბავშვის თვალებში მელანინის პიგმენტები უკვე წარმოიქმნა, მაგრამ ამ უჯრედების მომწიფებას გარკვეული დრო სჭირდება. სხვა სიტყვებით რომ ვთქვათ, პიგმენტაცია ჯერ სრულად ჩამოყალიბებული არ არის. ჩვეულებრივ, ბავშვის მუდმივი თვალის ფერი დაბადებიდან დაახლოებით 5 თვის შემდეგ იწყებს გამოკვეთას.'), baby_message_ka = COALESCE(baby_message_ka, 'მე ჩემს „ბუსუსებს“ ვიცილებ! 🐻 გახსოვთ, გითხარით, რომ ჩემი სხეული „ლანუგოდ“ წოდებული ბუსუსებით იყო დაფარული? ახლა, როცა ცხიმოვანი ფენა სითბოს მინარჩუნებს, ეს ბუსუსები სულ უფრო ნაკლებად მჭირდება. მათ ნელ-ნელა ცვენა დაიწყეს. მე უფრო გლუვი და რბილი ვხდები. დაბადებისას შესაძლოა ზურგზე ცოტა შემრჩეს, მაგრამ უმეტესობა გაქრება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ამ კვირებში, როდესაც ორსულობის დასასრულს უახლოვდებით, მნიშვნელოვანია იცოდეთ ნიშნები, რომლებიც მშობიარობის დაწყებაზე მიგანიშნებთ. ლორწოვანი საცობი შესაძლოა მშობიარობამდე 1 თვით ადრე ან სულ რამდენიმე საათით ადრე გამოვიდეს. მშობიარობის მოახლოების კიდევ ერთი ნიშანია სანაყოფე წყლების დაღვრა. ეს სითხე შეიძლება წყალივით თხელი და ძალიან ღია ყვითელი იყოს. სანაყოფე წყლები ზოგჯერ უეცრად იღვრება და ასეთ შემთხვევაში უმჯობესია დაუყოვნებლივ მიმართოთ სამშობიაროს. სანაყოფე წყლების დაღვრის შემდეგ ბავშვი ინფექციებისგან ნაკლებად დაცული რჩება.;;;
სანაყოფე წყლების დაღვრის შემდეგ საჭიროა ექიმის დაუყოვნებელი შეფასება და მშობიარობის მართვის გეგმის განსაზღვრა. რაც უფრო მეტი დრო გადის, ბავშვის ინფიცირების რისკი მით უფრო იზრდება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შუადღისას ხანმოკლე ძილმა (15-20 წუთი) შესაძლოა ენერგია აღგიდგინოთ. თუმცა დიდხანს ნუ დაიძინებთ, რადგან ღამის ძილი შეიძლება დაგერღვეთ. კიბეზე ჩამოსვლისას მოაჯირს ჩაეჭიდეთ.') WHERE id = '1dccc97f-570f-4f2a-ba96-d46cdb785a71';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ორსულობის 30 კვირა უკვე გაიარეთ. ძვლოვანი ქსოვილის სწრაფი ჩამოყალიბების შედეგად თქვენი ბავშვის ჩონჩხი საკმაოდ განვითარებულია. თუმცა თავის ქალის ძვლები ჯერ კიდევ ბოლომდე არ არის გაძვალებული. ეს ბავშვს სამშობიარო არხში უფრო ადვილად გავლაში ეხმარება.;;;
ყიფლიბანდი ეწოდება შემაერთებელი ქსოვილის უბანს, რომელიც ბავშვის თავის ქალის ძვლების შეერთების ადგილებში მათ სრულ გაძვალებამდე არსებობს. თავის ქალაზე 6 ყიფლიბანდია და მშობიარობის მოახლოებისას მათგან 5 უკვე დახურულია. ბავშვის დაბადების შემდეგ ღია მხოლოდ თავის წინა ნაწილში მდებარე ყიფლიბანდი რჩება. ბავშვის თავზე ყიფლიბანდის უბანი შემაერთებელი ქსოვილისგან შედგება. ეს აგებულება თავის ქალას მოქნილობას ანიჭებს და ძვლებს ერთმანეთზე მცირედ გადანაცვლების საშუალებას აძლევს, რის შედეგადაც თავი სამშობიარო არხში გადის და მშობიარობა შესაძლებელი ხდება. დაბადების შემდეგ თავის ქალის ზრდა ტვინის ზრდის გაგრძელების საშუალებას იძლევა. თავის ქალის ასეთი მოქნილი აგებულების წყალობით, ბავშვის ტვინის ზრდის დაახლოებით 75% სიცოცხლის პირველ 2 წელიწადში მიმდინარეობს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ტვინი იზრდება! 🧠 დედიკო, ჩემი ტვინი ახლა წარმოუდგენელი სისწრაფით ვითარდება. მასში მილიარდობით ახალი კავშირი წარმოიქმნება. მე უკვე მხოლოდ რეფლექსებით აღარ ვმოძრაობ — ვფიქრობ, ვგრძნობ და ვიმახსოვრებ. თქვენი ხმა ჩემი ყველაზე საყვარელი მოგონებაა.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'მესამე ტრიმესტრის დაწყებასთან ერთად შესაძლოა მშობიარობის შიში გაგიჩნდეთ. ზომიერი შფოთვა და მღელვარება ამ პერიოდში სრულიად ნორმალურია. თუმცა გადაჭარბებულმა ნერვიულობამ შესაძლოა როგორც თქვენზე, ისე თქვენს ბავშვზე უარყოფითად იმოქმედოს. განსაკუთრებით მაშინ, თუ ადრე არ გიმშობიარიათ, სიტუაცია შეიძლება უფრო რთულად მოგეჩვენოთ და გაურკვევლობით გამოწვეული დამატებითი შფოთვა განიცადოთ. ამ პერიოდში ახლობლების გვერდით ყოფნა და მეუღლის მხარდაჭერა დაგეხმარებათ, ეს ეტაპი უფრო მშვიდად გაიაროთ და შიშები შეამციროთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ცრუ შეკუმშვების დროს შეიცვალეთ პოზა, დალიეთ წყალი და ღრმად ისუნთქეთ. მარცხენა გვერდზე დაწოლამ შესაძლოა შეკუმშვები შეამსუბუქოს. წყალი ყოველთვის თან იქონიეთ, რადგან გაუწყლოებამ შეკუმშვები შეიძლება გააძლიეროს.') WHERE id = 'c04052f3-92f1-4783-8ceb-a4f9489af352';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ თქვენი ბავშვის ცრემლსადენი არხები უკვე ჩამოყალიბებულია, ამ არხების ნაწილი დაბადებისას დახურულია. ამიტომ დაბადებიდან გარკვეული დროის განმავლობაში ტირილისას ბავშვს თვალებიდან ცრემლები შეიძლება არ წამოუვიდეს. საცრემლე ჯირკვლების მიერ წარმოქმნილი ცრემლი ქვედა ქუთუთოზე არსებული ხვრელების გავლით ცხვირის ღრუში ჩაედინება. ეს მდგომარეობა შეიძლება ბავშვის დაბადებიდან დაახლოებით 3 კვირამდე გაგრძელდეს. ცრემლი გამჭვირვალე და მარილიანი სითხეა, რომელსაც თვალების ზედა ნაწილში მდებარე საცრემლე ჯირკვლები გამოყოფს. ის ხელს უწყობს თვალის დატენიანებას და ხახუნის თავიდან აცილებას. ამასთანავე, ცრემლს მნიშვნელოვანი ანტიბაქტერიული თვისებები აქვს. ის თვალის კაკლის საკუთარ ღრუში მოძრაობას უზრუნველყოფს და თვალში მოხვედრილი მტვრისა და უცხო ნაწილაკების გაუვნებელყოფას უწყობს ხელს. ცრემლის დაახლოებით 98% წყლისგან შედგება. დარჩენილ ნაწილში სისხლის პლაზმის შესაბამისი რაოდენობით შარდოვანა და უფრო მცირე რაოდენობით გლუკოზა, მარილები და ორგანული ნივთიერებებია. საცრემლე ჯირკვლები 3 სხვადასხვა სახის ცრემლს წარმოქმნის. ესენია: ბაზალური ცრემლი, რეფლექსური ცრემლი და ემოციური მიზეზებით გამოწვეული ცრემლი.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი აუზი პატარავდება! 🏊‍♂️ რაც უფრო ვიზრდები, ჩემ გარშემო არსებული წყალი მით უფრო ნაკლებად მყოფნის. აქ დაახლოებით 1 ლიტრი წყალია, მაგრამ იმდენ ადგილს ვიკავებ, რომ მოძრაობა მიჭირს. ახლა ჩემი იდაყვისა და მუხლის თითოეულ მოძრაობას უფრო მკვეთრად გრძნობ. ზოგჯერ გატკენ, მაპატიე.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'დიდი კომბოსტო'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის დროს ფინიკის მიღებას მრავალი სარგებელი აქვს. ფინიკი ცილებით, კალიუმით, მაგნიუმით, მანგანუმით, რკინით, სპილენძითა და B1, B2, B3, A1, C ვიტამინებით ძალიან მდიდარი ხილია. ბოჭკოს მაღალი შემცველობის წყალობით ის დანაყრების შეგრძნებას ქმნის და საჭმლის მომნელებელი სისტემის მუშაობის მოწესრიგებას უწყობს ხელს. ფინიკი სხვადასხვა ანტიოქსიდანტს შეიცავს და სასარგებლო ბუნებრივი ნახშირწყლების წყაროა. ის ასევე დიდხანს გაგრძნობინებთ დანაყრებას, ხელს უწყობს სისხლში შაქრის დონის რეგულირებას და ამგვარად ორსულობისას წონის კონტროლისთვის სასარგებლოა. ფოლიუმის მჟავის შემცველობის წყალობით ფინიკი მთელი ორსულობის განმავლობაში თქვენი ბავშვის ჯანსაღ განვითარებას უწყობს ხელს. ფინიკი შეიცავს ნივთიერებას, რომელსაც ოქსიტოცინი ეწოდება. ოქსიტოცინი საშვილოსნოს ყელის გარეგანი ჩარევის გარეშე, მარტივად გახსნას უწყობს ხელს. ამიტომ ფინიკი ბუნებრივი მშობიარობის ხელშემწყობ ერთ-ერთ მნიშვნელოვან საკვებად მიიჩნევა.;;;
მიუხედავად იმისა, რომ ამ საკითხზე ჯერ საბოლოო კვლევა არ არსებობს, ოქსიტოცინის შემცველობის გამო საშვილოსნოს ყელის ნაადრევად გახსნის შესაძლო რისკის გათვალისწინებით, ორსულობისას ფინიკის ჭარბი რაოდენობით მიღებისგან თავი უნდა შეიკავოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ქოშინის დროს გამართულად დადექით და ხელები თავს ზემოთ ასწიეთ. ეს ნეკნებს შორის სივრცეს აფართოებს. საკვები მცირე ულუფებით მიირთვით, რათა კუჭმა დიაფრაგმას დამატებით არ დააწვეს.') WHERE id = '676af173-b90a-4c64-a591-ff651fa5a3ea';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ზრდის ტემპმა უკვე „რეკორდულ“ მაჩვენებელს მიაღწია — ის ყოველ კვირას დაახლოებით 200 გრამს იმატებს! ასეთი სწრაფი მატება როგორც კანქვეშა ცხიმოვანი შრის გასქელებით, ისე შინაგანი ორგანოების წონის ზრდით არის განპირობებული. ამ კვირებში ფილტვები კვლავ განაგრძობს განვითარებას. მიუხედავად იმისა, რომ თქვენი ბავშვი საშვილოსნოში სუნთქვით ვარჯიშებს ასრულებს, მის ფილტვებს გარე გარემოში სრულიად დამოუკიდებლად ფუნქციონირებისთვის კიდევ რამდენიმე კვირა სჭირდება. ამ დროის განმავლობაში ფილტვებში არსებული ჰაერის პარკუჭები კიდევ უფრო ძლიერდება. თქვენი ბავშვის ძილის რეჟიმი უკვე უფრო მკაფიო და მოწესრიგებული გახდა. მას განსაზღვრულ საათებში სძინავს, სხვა დროს კი იღვიძებს და „ვარჯიშს“ აგრძელებს. მისი ძილის ციკლები უკვე ახალშობილი ბავშვის ძილის რეჟიმს ჰგავს.'), baby_message_ka = COALESCE(baby_message_ka, '31 კვირა! 🥥 გამარჯობა, დედიკო! მე უკვე ქოქოსის (coconut) ზომის ვარ. ჩემი წონა 1.5 კგ-ს აღწევს, სიგრძე კი 41 სმ-ია. უკვე საკმაოდ „მძიმეწონიანი“ ვარ. ახლა ჩემი მთავარი მიზანია, ფილტვები მომწიფდეს და მეტი ცხიმი დავაგროვო. ამქვეყნად მოსასვლელად ვემზადები!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'შეიძლება ნეკნების ტკივილმა და ქოშინმა შეგაწუხოთ. საშვილოსნო დიაფრაგმასა და ფილტვებს ზემოთ აწვება. ღრმად ჩასუნთქვა შეიძლება ფუფუნებადაც კი მოგეჩვენოთ. ბავშვის ფეხები შესაძლოა თქვენს ნეკნებს შორის მოექცეს.;;;
ასევე შეიძლება დაღლილობა და სისუსტე დაბრუნდეს. მუცლის სიმძიმემ, უძილო ღამეებმა და ორგანიზმის გაზრდილმა ენერგეტიკულმა მოთხოვნილებამ შეიძლება შუადღისთვის სრულიად გამოგფიტოთ. ნუ ეცდებით გმირობას — დასვენება გჭირდებათ. შესაძლოა წონასწორობის პრობლემაც გქონდეთ და ხშირად წაბორძიკდეთ, ამიტომ ფრთხილად იყავით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'კარგი დროა სამშობიაროს ჩანთის მომზადების დასაწყებად. შეადგინეთ სია და საჭირო ნივთები ნელ-ნელა შეაგროვეთ. აჩქარება საჭირო არ არის, თუმცა მზადყოფნა დაგამშვიდებთ.') WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვი დღეში დაახლოებით ნახევარ ლიტრ შარდს წარმოქმნის. ის ყლაპავს სანაყოფე წყლებს, წარმოქმნილ შარდს კი კვლავ სანაყოფე წყლებში გამოყოფს. ამგვარად იქმნება ციკლი და სითხე მუდმივად საჭირო დონეზე ნარჩუნდება. სანაყოფე წყლები არის სითხე, რომლის რაოდენობა და შემადგენლობა ორსულობის განმავლობაში მუდმივად იცვლება. ორსულობის პირველ კვირებში ის თქვენი სისხლის გაფილტვრის შედეგად წარმოიქმნება და ისეთი შემადგენლობა აქვს, რომელიც ბავშვს საკვებითა და ჟანგბადით უზრუნველყოფს. მომდევნო კვირებში სანაყოფე წყლების შემადგენლობა იცვლება და წყლის, არაორგანული მარილების, ცილების, ცხიმების, ნახშირწყლებისა და ფერმენტების გარდა, მე-12 კვირიდან ბავშვის მიერ წარმოქმნილ შარდსაც შეიცავს. ეს სითხე მნიშვნელოვან როლს ასრულებს თქვენი ბავშვის წოვის რეფლექსის ჩამოყალიბებასა და ფილტვების განვითარებაში. ამავე დროს, რადგან ბავშვს თავისუფლად შეუძლია გაჭიმვა, გადაბრუნება და სხვა მოძრაობების შესრულება, სანაყოფე წყლები ჩონჩხისა და კუნთოვანი სისტემის განვითარებასაც უწყობს ხელს. გარედან მიყენებული ნებისმიერი დარტყმის დროს სანაყოფე წყლები თქვენს ბავშვს იცავს. სანაყოფე წყლები საშუალოდ ყოველ 3 საათში განახლდება და მათი შემადგენლობაც იცვლება. ბავშვის მიერ წარმოქმნილი შარდიც მონაწილეობს სანაყოფე წყლების ცვალებადობაში.'), baby_message_ka = COALESCE(baby_message_ka, 'რა ფერის თვალები მაქვს? 👁️ ამჟამად, ყველა ბავშვის მსგავსად, მეც მუქი ლურჯი ან ნაცრისფერი თვალები მაქვს. დაბადების შემდეგ, სინათლესთან შეხებისას, ჩემი ნამდვილი თვალის ფერი (ყავისფერი, მწვანე ან თხილისფერი) გამოვლინდება. ამას შეიძლება 6-9 თვე დასჭირდეს. თუმცა, ნებისმიერ შემთხვევაში, სიყვარულით შემოგხედავ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'ზრდადი საშვილოსნო გარშემო მდებარე კუნთებისა და იოგების დაჭიმვას იწვევს, რის გამოც საშოში ტკივილი შეიძლება გაჩნდეს. თქვენში მზარდი ბავშვის ზემოქმედებით გაფართოებული საშვილოსნო სხეულის სიმძიმის ცენტრს ცვლის, რაც წელისა და მუცლის ქვედა ნაწილში ტკივილს იწვევს. მესამე ტრიმესტრში, როცა მუცელი მნიშვნელოვნად იზრდება, იოგების ამ დაჭიმვამ უეცარი მოძრაობისას შეიძლება საზარდულის მიდამოში მოქაჩვის ან დანის ჩხვლეტის მსგავსი ტკივილი გამოიწვიოს. ამის მიზეზი მრგვალი იოგის დაჭიმვაა.;;;
ორსულობისას საშვილოსნოს ტკივილი ხშირად საშოს ტკივილში ერევათ. ორსულობის ბოლო კვირებში საშვილოსნოს ყელის დარბილება და ნაწილობრივ გახსნა შეიძლება დაიწყოს. ეს პროცესი შესაძლოა მშობიარობამდე რამდენიმე კვირით ადრე დაიწყოს. გახსნისას საშოში ტკივილი შეიძლება ძლიერი და დანის ჩხვლეტის მსგავსი იყოს. ეს არ ნიშნავს, რომ სამშობიარო ტკივილები დაიწყო.'), daily_tip_ka = COALESCE(daily_tip_ka, 'საჯდომი ნერვის ტკივილის დროს მტკივნეულ მხარეს ნუ დაწვებით. მიიღეთ თბილი აბაზანა ან მტკივნეულ ადგილზე თბილი კომპრესი დაიდეთ. ექიმთან კონსულტაციის შემდეგ შეგიძლიათ ორსულებისთვის განკუთვნილი ფიზიოთერაპიით ან მასაჟით ისარგებლოთ.') WHERE id = 'ef1f18bb-3c48-4a2a-96b2-7141d5fc2528';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის თავის თმიან ნაწილზე შესაძლოა წარმოიქმნას შეშუპება, რომელსაც სამშობიარო სიმსივნე ეწოდება. ეს თავის ფორმირების პროცესს უკავშირდება. მოლდინგი არის მშობიარობის პროცესში ბავშვის თავის ფორმისა და გარკვეულწილად მოცულობის დროებითი ცვლილება. იმისათვის, რომ მშობიარობისას ბავშვის თავმა სამშობიარო არხში გაიაროს, ის არხის ფორმასა და ზომას უნდა მოერგოს. სამშობიარო არხში გავლისას ბავშვი თავს წინ ხრის, შიგნით აბრუნებს, უკან წევს და გარეთ ატრიალებს. ამ პროცესის დროს ბავშვის თავის ქალის ძვლები მათ შორის არსებული ელასტიკური ხრტილოვანი ქსოვილის წყალობით ერთმანეთს უახლოვდება და ნაწილობრივ ერთმანეთზე გადადის. სამშობიარო არხში გავლისას რბილი ქსოვილების სწრაფი ფორმირების შედეგად თავის არეში შესაძლოა დროებითი დეფორმაციები გამოჩნდეს. ახალშობილის თავის ქალის ფორმის ცვლილების მიზეზებს შორის შეიძლება იყოს ბავშვის მდებარეობა საშვილოსნოში, ხანგრძლივი და რთული მშობიარობა, ინკუბატორში ყოფნა ან კისრის კუნთების დამოკლება.'), baby_message_ka = COALESCE(baby_message_ka, 'თავით ქვემოთ ვარ? 🙃 დიდი ალბათობით, უკვე ვცდილობ, თავით ქვემოთ მდებარეობა (თავით წინამდებარეობა) მივიღო. ეს მშობიარობისთვის ყველაზე ხელსაყრელი პოზიციაა. მაგრამ თუ ჯერ არ გადავბრუნებულვარ, ნუ ინერვიულებთ, ჯერ კიდევ მაქვს დრო. მიზიდულობის ძალა მომწონს — რადგან თავი მძიმე მაქვს, ქვემოთ ჩასვლა უფრო მარტივია.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობა ქალის ცხოვრებაში ერთ-ერთი ის პერიოდია, როდესაც წონა ყველაზე სწრაფად იმატებს. ორსულობისას ჰორმონების დონის მატებისა და თქვენი ბავშვის განვითარების ხელშეწყობის საჭიროების გამო შესაძლოა ხშირად მოგშივდეთ. თუ შიმშილს მცირე წახემსებით არ შეამსუბუქებთ, ამან შეიძლება მაღალკალორიული საკვების დიდი ულუფებით მიღება გამოიწვიოს. ქალები, რომელთა სხეულის მასის ინდექსი ორსულობამდე ნორმალური ან დაბალი იყო, ამ პერიოდში საშუალოდ 10-12 კილოგრამს იმატებენ. ჭარბი წონის მქონე ქალები კი ორსულობისას უფრო მეტი წონის მომატებისკენ არიან მიდრეკილი. ამის მთავარი მიზეზია ის, რომ არაჯანსაღი კვების ჩვევების მქონე ქალები ამ პერიოდში ამ ჩვევებს კიდევ უფრო აძლიერებენ და აგრძელებენ.;;;
არაჯანსაღი, კვებითი ღირებულების არმქონე და „ცარიელი კალორიებით“ მდიდარი საკვების ნაცვლად, დღეში 3 ულუფა ხილი უნდა მიირთვათ, ძირითად კვებაზე ცილებით მდიდარი საკვები მიიღოთ, წახემსებისას აუცილებლად ჩართოთ რძე და რძის პროდუქტები და რეგულარულად შეასრულოთ მსუბუქი ვარჯიშები.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დაძინებამდე 2-3 საათით ადრე შეწყვიტეთ ჭამა. რძის დალევა ან ერთი მუჭა უმი ნუშის ჭამა კუჭის მჟავას განეიტრალებაში დაგეხმარებათ. მოერიდეთ მჟავე და ცხარე საკვებს.') WHERE id = '805cdfb6-2608-4845-b4aa-f6272786a6f0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'დაბადებისას თქვენი ბავშვის კანი შეიძლება მონაცრისფრო-მოლურჯო-იისფერი იყოს. გარდა ამისა, მისი სხეული ამნიონური სითხით არის სველი და ვერნიქსის ფენით დაფარული. როგორც კი ბავშვი სუნთქვას დაიწყებს, კანი ჯერ სახისა და სხეულის არეში, შემდეგ კი მოკლე დროში ხელებსა და ფეხებზე ვარდისფერდება და ნორმალურ შეფერილობას იღებს. ახალშობილის კანის გარეგნობა შეიძლება იმის მიხედვით იცვლებოდეს, ორსულობის რომელ ვადაზე დაიბადა ბავშვი. დღენაკლული ბავშვების კანი ძალიან თხელი და გამჭვირვალეა. მათი სხეული დაფარულია თხელი ბუსუსებით, რომლებსაც ლანუგო ეწოდება, და ისინი იბადებიან ხაჭოსებრი ვერნიქსის ფენით, რომელიც საშვილოსნოში ამნიონურ სითხეში ყოფნისას კანს იცავს. ორსულობის ვადის მატებასთან ერთად ბავშვის კანზე ვერნიქსისა და ლანუგოს რაოდენობა მცირდება. რადგან ბავშვის კანი ძალიან თხელია, ის შეიძლება ჩვეულებრივზე მეტად ვარდისფერი ჩანდეს. კანის ეს შეფერილობა კაპილარული სისხლძარღვებით არის გამოწვეული. ბავშვების თითქმის ნახევარი სახის არეში პატარა მუწუკების მსგავს თეთრ ან ყვითელ ბორცვებთან ერთად იბადება. ეს დახშული ცხიმოვანი ჯირკვლებია, რომლებიც მოკლე დროში თავისით ქრება.'), baby_message_ka = COALESCE(baby_message_ka, 'თითებს ვწოვ! 👍 ეს ჩემი საყვარელი საქმიანობაა. ულტრაბგერითი გამოკვლევისას ხშირად შეგიძლიათ დამინახოთ, როგორ ვწოვ ცერა თითს. ეს მამშვიდებს და ყბის კუნთებს მიძლიერებს. ვვარჯიშობ, რომ დაბადების შემდეგ თქვენი რძე მოვწოვო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობისას საშოს არეში შესაძლოა შემაწუხებელი ქავილი გაგიჩნდეთ. ამის მიზეზი შეიძლება იყოს ალერგია, გამაღიზიანებელი ქიმიური ნივთიერებები, გესტაციური დიაბეტი, კანის ისეთი დაავადებები, როგორიცაა ეგზემა, სქესობრივი გზით გადამდები ინფექციები ან სოკოვანი ინფექცია.;;;
ორსულობის დროს მიმდინარე ჰორმონული ცვლილებების გამო ვაგინალური ინფექციების განვითარების ალბათობა მნიშვნელოვნად იზრდება. თუ ქავილი ვაგინალური ინფექციით არის გამოწვეული, ამ არეში შეიძლება სიწითლე და შეშუპება გაჩნდეს. ქავილს შესაძლოა თან ახლდეს თეთრი, სქელი გამონადენიც. ვაგინალური ქავილი შეიძლება გააძლიეროს ორსულობისთვის შეუსაბამო კრემებისა და მალამოების, დამარბილებელი საპნებისა და სარეცხი საშუალებების, ვაგინალური სპრეებისა და სურნელოვანი ტუალეტის ქაღალდის გამოყენებამ. თუ საშოს არეში ქავილი გაწუხებთ, ექიმის რეკომენდაციით სამკურნალო და დამამშვიდებელი კრემებისა და მალამოების გამოყენება სიმპტომების შემცირებაში დაგეხმარებათ. გარდა ამისა, ტანსაცმელი სარეცხი ფხვნილის ნაცვლად საპნის ფხვნილით უნდა გარეცხოთ, ატაროთ ბამბის საცვლები და დღის განმავლობაში ხშირად გამოიცვალოთ, უპირატესობა მიანიჭოთ თავისუფალ, სხეულზე არამომდგარ ტანსაცმელს და საშოს მიდამო ყოველთვის სუფთა და შეძლებისდაგვარად მშრალი შეინარჩუნოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ხელების დაბუჟების შესამცირებლად ხშირად შეარხიეთ და მაღლა ასწიეთ ისინი. ღამით მაჯის ფიქსატორის ტარებამ შეიძლება ნერვზე ზეწოლა შეამციროს.') WHERE id = 'd4779c73-b7cd-4428-bca1-d013881798d5';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, '32-ე კვირისთვის თქვენი ბავშვის ხელის ფრჩხილები უკვე თითის წვერებამდეა გაზრდილი. ფეხის ფრჩხილები კი თითის წვერებს 36-ე კვირისთვის აღწევს. ბავშვის ფრჩხილები, რომელთა განვითარებაც 10-ე კვირას დაიწყო, კერატინისგან შედგება და მთელი სიცოცხლის განმავლობაში აგრძელებს ზრდას. ფრჩხილის სტრუქტურაში არსებული კერატინი დიდი რაოდენობით გოგირდის შემცველ ამინომჟავებს შეიცავს. ამ კვირებში თქვენი ბავშვი საკმაოდ ხშირად ასლოკინებს. მშობიარობის მოახლოებასთან ერთად სლოკინის სიხშირეც იზრდება. ბავშვები წოვის რეფლექსით იბადებიან. ეს რეფლექსი საშვილოსნოში ამნიონური სითხის ყლაპვისა და სლოკინის შედეგად ყალიბდება. ამ კვირაში ექიმთან ვიზიტისას ულტრაბგერითი გამოკვლევით შესაძლოა დაინახოთ კიდეც, როგორ ასლოკინებს თქვენი ბავშვი და როგორ წოვს თითს.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი 5 გრძნობა მუშაობს! 🖐️👃👂👀👅 მხედველობა, სმენა, გემო, ყნოსვა და შეხება. ჩემი ყველა გრძნობა გააქტიურებულია. თქვენი ხმა მესმის, თქვენს მიერ მირთმეული საკვების გემოს ვგრძნობ, სინათლეს ვხედავ და სახეზე ვეხები. მე ყველაფრის შემგრძნობი ცოცხალი არსება ვარ. თქვენ ჩემი სამყარო ხართ, დედიკო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'ემოციურად შესაძლოა „ბუდის მოწყობის“ ინსტინქტი გაგიძლიერდეთ. შეიძლება სახლის დალაგება, ბავშვის ტანსაცმლის გარეცხვა და დაუთოება მოგინდეთ. გამოიყენეთ ენერგიის ეს მოზღვავება, მაგრამ თავს ზედმეტად ნუ გადაიღლით.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შეშუპების შესამცირებლად განაგრძეთ დიდი რაოდენობით წყლის სმა და მარილის მიღება მინიმუმამდე შეამცირეთ. წელის ტკივილის დროს აუცილებლად გამოიყენეთ ორსულობის ბალიში და ეცადეთ, გამართული იჯდეთ. თუ ჯერ არ გაგიკეთებიათ, ახლა საუკეთესო დროა ბავშვის ოთახის ბოლო დეტალების დასასრულებლად ან ისეთი დიდი ნივთების შესაძენად, როგორიცაა საბავშვო ეტლი, რადგან მომდევნო კვირებში გადაადგილება შეიძლება უფრო გაგიჭირდეთ.') WHERE id = 'a8ac9e30-a252-4631-aca6-20ffff4ecf20';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის ძვლებს "პირველადი ძვლოვანი ქსოვილი" ეწოდება, რაც იმას ნიშნავს, რომ ისინი ჯერ სრულად მომწიფებული არ არის. დედის საშვილოსნოში ბავშვის ძვლების შემაერთებელი ქსოვილი ჯერ სრულად ჩამოყალიბებული და საკმარისად გამაგრებული არ არის. ძვლები ჩონჩხის სისტემის ნაწილია, რომელიც სხეულს იცავს, გამართულად დგომასა და საყრდენს უზრუნველყოფს და სხეულის მოძრაობაში მონაწილეობს. ამავდროულად, ისინი სისხლის წარმოქმნაზე პასუხისმგებელი ძვლის ტვინის წარმოქმნის ადგილიცაა. ძვლოვანი ქსოვილი ორგანიზმში კალციუმის მარაგის ფუნქციას ასრულებს და ორგანიზმის ყოველდღიური მოთხოვნილება კალციუმზე ამ მარაგიდან ივსება.;;;
თქვენი ბავშვის ნაწლავებში მეკონიუმის დაგროვება გრძელდება. მეკონიუმი ბავშვის ნერწყვისგან, კუჭისა და პანკრეასის სეკრეტისგან, უჯრედული ნარჩენებისგან, ლორწოსა და ლანუგოს ღინღლისგან შედგება. ნაწლავებში ყოფნის პერიოდში ის სტერილურია. დაბადებიდან 48 საათის განმავლობაში მეკონიუმი ორგანიზმიდან გამოიყოფა.'), baby_message_ka = COALESCE(baby_message_ka, 'მე შარდს გამოვყოფ! 🚽 სასაცილოდ ჟღერს, მაგრამ დღეში დაახლოებით ნახევარ ლიტრ შარდს გამოვყოფ და მას ამნიონურ სითხეს ვურევ. შემდეგ ამ სითხეს ისევ ვყლაპავ. ეს ციკლი აჩვენებს, რომ ჩემი თირკმელები და საჭმლის მომნელებელი სისტემა ჯანმრთელია. ჩემს სითხეს თავად ვარეგულირებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ქოქოსი'), body_changes_ka = COALESCE(body_changes_ka, 'ხელებისა და ფეხების შეშუპება შესაძლოა დილაობითაც გაგრძელდეს. თუ სახე უეცრად შეგიშუპდათ, არტერიული წნევა გაიზომეთ. ასევე, "Carpal Tunnel Syndrome"-ის (კარპალური გვირაბის სინდრომის) გამო ხელებში შეიძლება დაბუჟება და ტკივილი იგრძნოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'კომფორტული ფეხსაცმლის ტარება ძალიან მნიშვნელოვანია. მაღალქუსლიან ფეხსაცმელზე სრულად თქვით უარი. წელის ტკივილის დროს ორსულთა დამჭერი ქამრის ტარება შეიძლება სასარგებლო იყოს.') WHERE id = 'b1c4365d-e81a-4bcf-93eb-e36cdbc64c30';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირაში, როდესაც მე-8 თვეში შედიხართ, ფილტვების განვითარება სწრაფად გრძელდება. 28-36-ე კვირებს შორის ფილტვები "საკულარულ" სტადიაზეა. ამ პერიოდში, როდესაც ფილტვები ტომრისებრი ფორმისაა, ბრონქების წარმომქმნელი ზედაპირული შრე თხელდება, ფილტვებში კი კაპილარების რაოდენობა სწრაფად იზრდება. როდესაც თქვენი ბავშვის ფილტვების განვითარება სრულად დასრულდება, დაახლოებით 300 მილიონი ჰაერის ბუშტუკი ჩამოყალიბდება. მალე ამ ბუშტუკების ზედაპირი მთლიანად დაიფარება ნივთიერებით, რომელსაც სურფაქტანტი ეწოდება. სურფაქტანტი ამ ბუშტუკებში აირთა ცვლას უწყობს ხელს და ზედაპირულ დაჭიმულობას ამცირებს, რაც ფილტვებს ყველაზე ღრმა ჩასუნთქვის დროსაც კი შეუფერხებლად მუშაობის საშუალებას აძლევს. ნაადრევი მშობიარობის რისკის მქონე ორსულებისთვის დანიშნული ფილტვების მომწიფების ხელშემწყობი ინიექციები ფილტვებში სურფაქტანტის გამომუშავებას აჩქარებს. შედეგად, ნაადრევად დაბადებულ ბავშვებს სუნთქვის გაძნელება უფრო ხანმოკლე პერიოდის განმავლობაში აღენიშნებათ.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ფილტვები მწიფდება! 🌬️ ჩემს ფილტვებში ალვეოლები ყოველდღიურად უფრო მეტად ვითარდება. "სურფაქტანტის" რაოდენობა იზრდება. ახლა რომ დავიბადო, დახმარება ჯერ კიდევ დამჭირდება, თუმცა ჩემი გადარჩენის შანსი ძალიან მაღალია. ყოველდღიურად უფრო ძლიერი ვხდები. თქვენ უბრალოდ ცოტა მეტი დრო მომეცით.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სალათის ფოთოლი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ დღეებში, როდესაც მე-8 თვეში შედიხართ, თვეში 2-4 კილოგრამის, ხოლო კვირაში საშუალოდ 500 გრამის მომატება ნორმალურია. ამ კვირებში ბავშვის სწრაფი განვითარების გამო თქვენი მუცელი საგრძნობლად გაიზარდა და მოძრაობა საკმაოდ შეგეზღუდათ. გაზრდილმა მუცელმა შეიძლება გულძმარვა და ქოშინი გამოიწვიოს. ასეთი პრობლემების დროს მცირე ულუფებითა და ხშირად კვება და მარცხენა გვერდზე წოლა ძალიან სასარგებლო იქნება. ამ კვირებში სიარული და მჯდომარე მდგომარეობიდან წამოდგომა შესაძლოა საკმაოდ გაგიჭირდეთ. ამის მიზეზი ორსულობის განმავლობაში სახსრებისა და კუნთების მოდუნებაა. მიუხედავად იმისა, რომ ამ მიზეზების გამო მოძრაობა რთულია, უმოძრაობამ შეიძლება მდგომარეობა კიდევ უფრო გააუარესოს. საკმარისი იქნება ხანმოკლე გასეირნება და მსუბუქი ვარჯიში ისე, რომ თავი არ გადაიღალოთ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის შესამცირებლად მცირე ულუფებით, მაგრამ ხშირად მიირთვით. ძილისას მარცხენა გვერდზე დაწოლას მიანიჭეთ უპირატესობა; ეს ხელს შეუწყობს როგორც თქვენს საჭმლის მონელებას, ისე ბავშვის სისხლის მიმოქცევას. წელის ტკივილის დროს აუცილებლად გამოიყენეთ ზურგის საყრდენი ბალიშები. დღეს საკუთარ თავს ცოტა დრო დაუთმეთ და ბავშვისთვის სამშობიარო ჩანთის სიის შედგენა დაიწყეთ.') WHERE id = '073c7d59-96b0-4ee4-a0d5-1e595fd135fb';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მე-8 თვის დასაწყისში, 32-ე კვირაში, ცხიმოვანი და კუნთოვანი ქსოვილების ზრდა სწრაფად გრძელდება. ამის გამო კანი უფრო რბილი და გლუვი ხდება. კანქვეშ დაგროვებული ცხიმის წყალობით კანის გამჭვირვალე იერი უკვე თითქმის მთლიანად გაქრა. ამ კვირიდან იწყება თქვენი ბავშვის სხეულის დამფარავი ლანუგოს ღინღლის ცვენაც. ლანუგო ეწოდება აბრეშუმივით წვრილ ღინღლს, რომელიც თქვენი ბავშვის სხეულს 20-ე კვირის შემდეგ ფარავს. ეს ღინღლი უფერული და რბილია და უფრო ხშირია შუბლის, ზურგისა და სახის არეებში. იმ პერიოდში, როდესაც კანი თხელია, ლანუგო ბავშვის სხეულის სითბოს შენარჩუნებასა და ინფექციებისგან დაცვას უწყობს ხელს. ნაადრევად დაბადებულ ბავშვებში ეს ღინღლი ხშირად გვხვდება და დაბადებიდან მალევე იწყებს ცვენას.'), baby_message_ka = COALESCE(baby_message_ka, 'მე სუნთქვას ვვარჯიშობ 🌬️ დედიკო, ჩემი გულმკერდი რიტმულად იწევა და ეშვება. ამნიონურ სითხეს ფილტვებში ვისუნთქავ და შემდეგ უკან გამოვუშვებ. ეს ჩემს კუნთებს აძლიერებს, რათა დაბადებისას პირველი და ყველაზე მნიშვნელოვანი ჩასუნთქვა შევძლო. ზოგჯერ შეიძლება ჩემი რიტმული მოძრაობები (სლოკინი) იგრძნოთ. ეს ჩემი ვარჯიშია!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სალათის ფოთოლი'), body_changes_ka = COALESCE(body_changes_ka, 'ამ პერიოდში ერთფეროვან კვებას უნდა მოერიდოთ. დაბალანსებული და სრულფასოვანი კვება თქვენი ორგანიზმის ყველა ვიტამინისა და მინერალის საჭიროებას დააკმაყოფილებს. პირველ სამ თვეში ნაყოფის საჭიროებებისთვის დამატებითი კალორიების მიღება აუცილებელი არ არის. მეორე ტრიმესტრიდან ბავშვის განვითარებისთვის საკმარისია დღეში დამატებით 300 კალორიის მიღება. უნდა იცოდეთ, რომ საჭიროზე მეტი კალორიის მიღება ბავშვს სარგებელს არ მოუტანს და ზედმეტი კალორიები თქვენს ორგანიზმში ცხიმის სახით დაგროვდება. სასურველია, უკვე მოამზადოთ ტანსაცმელი და სხვა ნივთები, რომლებიც საავადმყოფოში თქვენ და თქვენს ბავშვს დაგჭირდებათ.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დღის განმავლობაში აუცილებლად მიირთვით კალციუმით მდიდარი საკვები, რადგან თქვენი ბავშვის ძვლები ახლა ყველაზე სწრაფი გამაგრების ეტაპზეა. წელის ტკივილის შესამსუბუქებლად რეგულარულად შეასრულეთ მსუბუქი გაჭიმვის ვარჯიშები, ხოლო ძილისას მარცხენა გვერდზე დაწოლას მიანიჭეთ უპირატესობა.') WHERE id = '6dc5213e-1c8a-4a6b-8be6-3e050cac8345';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'მიუხედავად იმისა, რომ მე-3 ტრიმესტრში თქვენი ბავშვის ტვინი სწრაფად განაგრძობს განვითარებას, თავის ზრდის ტემპი სხეულის სხვა ნაწილებთან შედარებით უფრო ნელია. ბავშვის ტვინის ჩამოყალიბება საშვილოსნოში მე-3 კვირიდან იწყება. ნერვული სისტემა ბავშვის მუცლადყოფნის პერიოდში ერთ-ერთი ყველაზე ადრე წარმოქმნილი სისტემაა, რომლის განვითარებაც დაბადების შემდეგ ყველაზე გვიან სრულდება. ამ კვირიდან ნეირონების ფორმირება სრულდება. გასული 9 კვირის განმავლობაში ნეირონები სხვადასხვა ტიპად დაიყო და მათი რაოდენობა მრავალჯერ გაიზარდა. 32-ე კვირაში ისინი ტვინის ყველაზე გარე შრის, ანუ ქერქის ქვედა უბნებისკენ გადაადგილებას იწყებენ. სწორედ ამ პროცესში სრულდება ტვინისა და ნერვული სისტემის ძირითადი სტრუქტურის ჩამოყალიბება. მშობიარობის დროისთვის ტვინი უკვე თითქმის საბოლოო სახეს იღებს და შემდგომ მისი სტრუქტურა თითქმის აღარ იცვლება.'), baby_message_ka = COALESCE(baby_message_ka, 'ხუთივე გრძნობა მუშაობს! 🖐️ უკვე სრულად აღჭურვილი ვარ: ვხედავ, მესმის, გემოსა და სუნს ვგრძნობ და შეხებასაც აღვიქვამ. შენს ხმას რომ ვიგონებ, თავს ვაბრუნებ. სინათლის მოხვედრისას თვალებს ვახამხამებ. ამნიონური სითხის გემოთი ვხვდები, რა შეჭამე. მზად ვარ, სამყარო შევიცნო!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სალათის თავი'), body_changes_ka = COALESCE(body_changes_ka, 'მედიცინაში იმ ემოციურ მდგომარეობას, რომელსაც მუცლად მყოფი ბავშვი დედის მეშვეობით განიცდის, „ემბრიონის ფსიქოლოგიას“ უწოდებენ. ორსულობის განმავლობაში, დედის ემოციური სამყაროს ჩამოყალიბების პარალელურად, მუცლად მყოფი ბავშვის ემოციური სამყაროც იმავე მოვლენების გავლენით ყალიბდება. გენეტიკური ხასიათის გარდა, ბავშვს ფსიქოლოგიური ხასიათიც აქვს, რომელიც საშვილოსნოში მისი ჩამოყალიბების პირველივე მომენტიდან ვითარდება. ფსიქოლოგიური ხასიათი მეორე ხასიათია, რომელიც გენეტიკურ ხასიათზე დედის ბედნიერების, აღელვების, ბრაზისა და მწუხარების გავლენით შენდება. საშვილოსნოში დაწყებული ამ ხასიათის ჩამოყალიბება 6 წლამდე გრძელდება და ადამიანის მთელ ცხოვრებაზე ახდენს გავლენას. არასოდეს დაგავიწყდეთ, რომ თქვენი ბავშვი თქვენზე არა მხოლოდ ფიზიოლოგიურად, არამედ ფსიქოლოგიურადაც არის დამოკიდებული.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ტანსაცმლის დასაცავად შეგიძლიათ მკერდის საფენები გამოიყენოთ. ძუძუსთავები საპნით არ დაიბანოთ, რადგან საპონი მათ აშრობს და ნახეთქებს აჩენს. მხოლოდ თბილი წყლით დაბანა საკმარისია.') WHERE id = 'fc626924-530b-4871-85a2-84474a5bcec0';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამნიონური სითხე სტერილური, უფერო და დამცავი სითხეა, რომელშიც ბავშვი იმყოფება. მართალია, მას ნაწილობრივ საშვილოსნოში არსებული "ამნიონური უჯრედები" წარმოქმნის, თუმცა მისი ძირითადი წყარო დედის ორგანიზმია. ეს სითხე ბავშვს საშვილოსნოში თავისუფლად მოძრაობის საშუალებას აძლევს და ამავდროულად იცავს დარტყმებისგან, ინფექციებისა და ტემპერატურის ცვლილებებისგან. ამნიონური სითხე ორსულობის განმავლობაში ტემპერატურას მუდმივად 37 გრადუსზე ინარჩუნებს, რის გამოც ბავშვზე ზამთრის სიცივე და ზაფხულის სიცხე გავლენას ვერ ახდენს. მე-2 ტრიმესტრში ამნიონური სითხის რაოდენობა ბავშვის წონის მატების პარალელურად იზრდება. 32-ე კვირისთვის სითხის მოცულობა 1 ლიტრს აღწევს, რაც მისი მაქსიმალური რაოდენობაა. იმისთვის, რომ ბავშვმა მეტი წონა მოიმატოს, ამ კვირიდან მშობიარობამდე ამნიონური სითხის მოცულობა დაახლოებით 150-250 მლ-ით მცირდება და საშუალოდ 750-800 მლ-ის ფარგლებში სტაბილურდება.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ფრჩხილები ძალიან გრძელია! 💅 ფრჩხილები უკვე თითის წვერებს სცდება. ზოგჯერ შემთხვევით სახეს ვიკაწრავ. როცა დავიბადები, ჩემთვის ხელთათმანები ან ფრჩხილის მაკრატელი მოამზადე. საკუთარ თავზე ზრუნვა ჯერ არ შემიძლია. შენ დამეხმარები, ხომ ასეა?'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სალათის თავი'), body_changes_ka = COALESCE(body_changes_ka, 'ქოშინმა შეიძლება დაგღალოთ. საშვილოსნო თითქმის უმაღლეს წერტილს, ნეკნების რკალს, აღწევს. ის დიაფრაგმას აწვება და ფილტვებს სრულად გაშლის საშუალებას არ აძლევს. კიბეზე ასვლა ან სწრაფად სიარული უფრო რთული ხდება.;;;
მკერდიდან "კოლოსტრუმის" გამოყოფა შეიძლება გაძლიერდეს. თქვენი ორგანიზმი მშობიარობის შემდგომი პირველი კვებისთვის "ოქროს სითხეს" ამზადებს. მკერდი შეიძლება უფრო მძიმე და მგრძნობიარე გახდეს. მუცლის კანი მაქსიმალურად არის დაჭიმული.'), daily_tip_ka = COALESCE(daily_tip_ka, 'შარდის ბუშტზე ზეწოლის შესამცირებლად კოფეინიანი სასმელები მინიმუმამდე შეამცირეთ, რადგან მათ შარდმდენი მოქმედება აქვს. წელის ტკივილის შესამსუბუქებლად ძილის დროს პატარა ბალიშები ფეხებს შორის და მუცლის ქვეშ მოათავსეთ. განაგრძეთ კალციუმისა და რკინის მიღება, რადგან ბავშვი ამჟამად ამ ელემენტებს სწრაფად "იმარაგებს". დღეს ზედმეტად ნუ გადაიღლებით.') WHERE id = 'b016d6e4-baac-45d0-93bb-1a801a1ac462';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენს ბავშვს მე-16 კვირიდან ესმის, ამ კვირის ბოლოს კი უკვე მოსმენილის დამახსოვრება და მასზე რეაგირება შეუძლია. ბავშვი მშობლების ხმების ამოცნობას იწყებს. როდესაც ერთ-ერთი მშობელი ელაპარაკება, ის ღელდება, გულისცემა უჩქარდება და რეაგირებას ცდილობს. ეს მდგომარეობა მიუთითებს, რამდენად სწრაფად ვითარდება ბავშვის ტვინი. მიუხედავად იმისა, რომ ამ პერიოდის ბოლოს ფილტვებს უკვე შეუძლია აირთა ცვლა, ისინი ჯერ კიდევ არ არის საკმარისად მომწიფებული. სრულად განვითარების შემდეგ ფილტვები მიკროორგანიზმებისგან დაცვაშიც მონაწილეობს. გარდა ამისა, ისინი სითხისა და ელექტროლიტების ბალანსის რეგულირებაში ასრულებს როლს. არეგულირებს სისხლში წყალბადისა და იოდის ბალანსს. ასევე ხელს უწყობს მეტყველებისთვის აუცილებელი ზოგიერთი ბგერის წარმოქმნას.'), baby_message_ka = COALESCE(baby_message_ka, '32 კვირის ვარ! 🎃 უკვე სალათის თავის ზომა ვარ! ახლა უკვე "მძიმე წონოსანი" ვარ. საშვილოსნოში ადგილი აღარ მყოფნის. ფეხებს ბოლომდე ვეღარ ვშლი, ამიტომ "ფეტალურ პოზაში" ვიმყოფები. ეს ჩემთვის ყველაზე კომფორტული პოზაა.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სალათის თავი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში სისხლში ესტროგენის მაღალი დონე ორგანიზმში სეკრეციის გაძლიერებას იწვევს. შედეგად, ორსულობამდელ პერიოდთან შედარებით უფრო მეტი ლორწო წარმოიქმნება, რამაც ცხვირის შიგნით სისხლძარღვების შეშუპება შეიძლება გამოიწვიოს. ეს ცხვირის გაჭედვასა და ორსულებში დისკომფორტის შეგრძნებას იწვევს. მასაჟი ცხვირის არხებში სისხლის მიმოქცევას აუმჯობესებს და ლორწოს სიბლანტეს ამცირებს. შედეგად, სუნთქვა გიმარტივდებათ. ცხვირის გაჭედვის შემსუბუქებაში ასევე დაგეხმარებათ საკმარისი წყლის მიღება, თბილი შხაპი, ცხვირის ირგვლივ თბილი კომპრესის დადება და თავის უფრო მაღლა მოთავსება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ექიმთან ვიზიტებს ნუ გამოტოვებთ. ამ კვირებში არტერიული წნევის გაზომვა და შარდში ცილის შემოწმება ("პრეეკლამფსიის" რისკის გამო) ძალიან მნიშვნელოვანია. თუ თავის ტკივილი ან მხედველობის დაბინდვა გაქვთ, დაუყოვნებლივ აცნობეთ ექიმს.') WHERE id = '33dd2de9-c534-420c-8e3d-e027683ad6e9';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვის კანზე წარმოქმნილმა ვერნიქსის ფენამ ოპტიმალურ რაოდენობას მიაღწია. ვერნიქსის ფენის დანიშნულებაა, ბავშვს ჯერ კიდევ საშვილოსნოში ყოფნისას დამცავი გარეთა საფარი შეუქმნას. მისი შემადგენლობაა 80% წყალი, 10% ცხიმი და 10% ცილოვანი ნაერთები.;;;
მშობიარობის დროს კი მისი დანიშნულებაა კანის დაცვა ჰაერის გამომშრალი ზემოქმედებისა და მავნე მიკროორგანიზმებისგან, კანში წყლის შენარჩუნებით გამოშრობის თავიდან აცილება, კანის pH ბალანსის გარკვეულ დონეზე შენარჩუნება და ბავშვის დაცვა მშობიარობისას შესაძლო ინფექციებისა და დაზიანებებისგან.'), baby_message_ka = COALESCE(baby_message_ka, 'მე სიზმრებს ვხედავ! 💤 ჩემი ტვინის ტალღები აჩვენებს, რომ ღრმა და მსუბუქი ძილის ფაზებს გავდივარ. ძილში ვიღიმი, სახეს ვჭმუხნი და თვალებსაც კი ვამოძრავებ. ჩემი ტვინი უკვე ზრდასრული ადამიანის ტვინივით იწყებს მუშაობას. მე მეოცნებე ბავშვი ვარ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'სალათის ფოთოლი'), body_changes_ka = COALESCE(body_changes_ka, 'ღამით უძილობამ და ფეხების კრუნჩხვებმა შეიძლება დაგღალოთ. გაზრდილი მუცელი საწოლში გადაბრუნებას ართულებს. წონასწორობის დარღვევის გამო ნელა იმოძრავეთ. უძილობამ შეიძლება გაღიზიანებული გაგხადოთ, თუმცა ეცადეთ, შუადღისას დაისვენოთ.;;;
შარდის ბუშტზე ზეწოლა შეიძლება გაიზარდოს, თუმცა გულძმარვა და ქოშინი ოდნავ შემცირდეს. ბავშვის თავის ქვემოთ ჩასვლისას ზედა ორგანოებზე ზეწოლა მცირდება, ქვედა ორგანოები კი (შარდის ბუშტი, მენჯის ძვლები) უფრო მეტად იჭყლიტება. შესაძლოა, „პინგვინის სიარულით“ დაიწყოთ სიარული.'), daily_tip_ka = COALESCE(daily_tip_ka, 'ფეხების შეშუპების შესამცირებლად განაგრძეთ ბევრი წყლის სმა და მარილის მიღება მინიმუმამდე დაიყვანეთ. ჯდომისას ეცადეთ, ზურგი სწორად გეჭიროთ, რათა ფილტვები უფრო თავისუფლად გაიშალოს. ეს კვირა საუკეთესო დროა მშობიარობის გეგმის დასაზუსტებლად (საავადმყოფოს არჩევა, ექიმთან კონსულტაცია). საღამოობით მუცელზე მსუბუქი მასაჟი გაიკეთეთ — თქვენი ბავშვი ამ შეხებას უკვე ძალიან მკაფიოდ გრძნობს.') WHERE id = '7757d4d7-3e07-45ad-b80b-78b87e96663b';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'თქვენი ბავშვი უჩვეულოდ სწრაფად განაგრძობს ზრდას! ორსულობის მესამე ტრიმესტრში კვირაში საშუალოდ დაახლოებით 500 გრამს იმატებთ. მომატებული წონის თითქმის ნახევარს ბავშვი საკუთარ სხეულში ცხიმოვანი ქსოვილის სახით აგროვებს. ცხიმოვანი უჯრედების ასეთი სწრაფი წარმოქმნის მთავარი მიზეზია, რომ დაბადების შემდეგ ბავშვმა საკუთარი სხეულის ტემპერატურის შენარჩუნება შეძლოს და საჭიროების შემთხვევაში ცხიმი ენერგიის წყაროდ გამოიყენოს. ამ ეტაპზე ბავშვის სხეულში როგორც ყავისფერი, ისე თეთრი ცხიმოვანი უჯრედებია. ყავისფერი ცხიმოვანი უჯრედები მედიცინაში ფეტალური ცხიმოვანი ქსოვილის სახელითაა ცნობილი. ბავშვებს ის ზრდასრულებზე მეტი აქვთ, რათა სხეულის სითბო ეფექტურად შეინარჩუნონ. ყავისფერი ცხიმოვანი უჯრედები ამას თერმოგენინის სახელით ცნობილი ცილის დახმარებით ახერხებენ, რომელიც მათ სტრუქტურაში უხვად არსებული მიტოქონდრიების გარეთა მემბრანაზე მდებარეობს. თერმოგენინის ცილა სისხლძარღვების მეშვეობით უჯრედებამდე მიტანილ ჟანგბადს იყენებს და სითბოს ეფექტურ წარმოქმნას უზრუნველყოფს.'), baby_message_ka = COALESCE(baby_message_ka, 'თავს ქვემოთ ვაბრუნებ! ⬇️ მიზიდულობის ძალა და ჩემი ინსტინქტები თავდაყირა მოთავსებისკენ მიბიძგებს. თავი ჩემი სხეულის ყველაზე მძიმე ნაწილია, ამიტომ მისი ქვემოთ მოქცევა მოსახერხებელია. ეს მშობიარობისთვის საუკეთესო პოზიციაა. თუ ჯერ არ გადავბრუნებულვარ, ნუ ინერვიულებთ — ზოგიერთი ჩემი მეგობარი ბოლო წუთამდე იცდის.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის მესამე ტრიმესტრში შესაძლოა ძლიერი ქოშინი იგრძნოთ. ორსულობისას სისხლში მნიშვნელოვნად მომატებული პროგესტერონი თავის ტვინში სუნთქვის ცენტრს ააქტიურებს, რის გამოც უფრო ხშირად და ღრმად სუნთქავთ. თქვენს სასუნთქ სისტემას მეტი ჰაერი სჭირდება, რათა სისხლმა პლაცენტას დიდი რაოდენობით ჟანგბადი მიაწოდოს და ჩვეულებრივზე მეტი ნახშირორჟანგი გამოდევნოს. ყველა ამ მიზეზის გამო, ყოველი ჩასუნთქვა-ამოსუნთქვისას თქვენი ფილტვები 30-40% მეტ ჰაერს ატარებს. ამ ცვლილებებმა შეიძლება სუნთქვის გაძნელება და ჰაერის უკმარისობის შეგრძნება გამოიწვიოს. მარცხენა გვერდზე წოლა, დამღლელი საქმიანობისგან თავის შეკავება, სწორად ჯდომა და გამართული სუნთქვა ამ პრობლემას შეგიმსუბუქებთ და უკეთ გაგრძნობინებთ თავს.'), daily_tip_ka = COALESCE(daily_tip_ka, 'განაგრძეთ კეგელის ვარჯიშების შესრულება. მენჯის ფსკერის კუნთების გაძლიერება დაგეხმარებათ, მართოთ ბავშვის თავის ქვემოთ ჩასვლით გამოწვეული ზეწოლა და თავიდან აიცილოთ შარდის შეუკავებლობა.') WHERE id = '7324ee36-63a7-4db4-bc5e-2444adb29718';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ კვირისთვის შესაძლოა, თქვენმა ბავშვმა უკვე დაიკავა მშობიარობისთვის საჭირო პოზიცია. ჩვეულებრივ, ბავშვები 32-ე კვირის შემდეგ იწყებენ მშობიარობისთვის საჭირო პოზიციის დაკავებას. მიუხედავად იმისა, რომ ეს საშუალო ვადაა, ბავშვი შეიძლება 4 კვირით ადრე ან უშუალოდ მშობიარობის დროსაც კი გადაბრუნდეს. მშობიარობის პოზიციაში ბავშვის თავი ქვემოთაა მოქცეული, დუნდულები თქვენი დიაფრაგმის ქვეშაა განთავსებული, ფეხები მუცლისკენ აქვს მოხრილი, ხელები კი მკერდზე გადაჯვარედინებული. ბავშვის მიერ დაკავებულ მშობიარობის ამ ნორმალურ პოზიციას ცეფალური ანუ თავით წინ მდებარეობა ეწოდება. >:P ფიზიოლოგიური მშობიარობისთვის აუცილებელია, რომ თავი მენჯის ღრუში გარკვეული სახით მოთავსდეს. მშობიარობის პოზიციაში ბავშვის წინამდებარე ნაწილი კეფის მიდამოში არსებული გამობურცულობაა. ამის წყალობით ბავშვის თავი ძვლოვან სამშობიარო არხში შესაძლო უმცირესი დიამეტრით შედის.'), baby_message_ka = COALESCE(baby_message_ka, 'თქვენგან იმუნურ დაცვას ვიღებ! 🛡️ დედიკო, პლაცენტის მეშვეობით თქვენგან ჩემთან „ანტისხეულები“ (მიკრობებთან მებრძოლი ჯარისკაცები) გადმოდის. ეს ჩემი პირველი ვაქცინაა. დაბადებისას ჩემი საკუთარი იმუნიტეტი სუსტი იქნება, მაგრამ თქვენგან მიღებული ეს დაცვა პირველ თვეებში დაავადებებისგან დამიცავს. თქვენ ჩემი მფარველი ანგელოზი ხართ!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'საჭმლის მონელების დარღვევა და შეკრულობა შესაძლოა კვლავ პრობლემად დარჩეს. პროგესტერონისა და ნაწლავებზე საშვილოსნოს ზეწოლის გამო საჭმლის მომნელებელი სისტემა შენელებულად მუშაობს. მნიშვნელოვანია ბევრი წყლის სმა და ბოჭკოვანი საკვების მიღება.'), daily_tip_ka = COALESCE(daily_tip_ka, 'გულძმარვის შესამცირებლად ხშირად და მცირე ულუფებით იკვებეთ. ძილისას მარცხენა გვერდზე წოლა სუნთქვასაც შეგიმსუბუქებთ და ბავშვისკენ სისხლის მიმოქცევასაც გააუმჯობესებს. თუ ჯერ არ დაგიწყიათ, დაგეგმეთ, რა უნდა ჩაალაგოთ სამშობიაროს ჩანთაში. არ დაგავიწყდეთ დასვენება და ეცადეთ, ზედმეტად არ გადაიღალოთ!') WHERE id = '2bbb9ba5-0677-4713-8d4c-c7c237ab84f6';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ამ ეტაპზე თქვენი ბავშვის სიგრძე შეიძლება საკმაოდ ფართო დიაპაზონში — 40-48 სმ-ის ფარგლებში მერყეობდეს. სიმაღლეში ზრდა ძირითადად ძვლების დაგრძელების ხარჯზე ხდება. ძვლების დაგრძელება არის პროცესი, რომელიც ბავშვის მუცლადყოფნისას, ემბრიონული პერიოდის ბოლოს იწყება და დაბადებიდან მოზარდობის დასრულებამდე გრძელდება. ზრდის ტემპი პერიოდულად შეიძლება აჩქარდეს ან შენელდეს. ბიჭებისა და გოგონების ზრდის პერიოდები ერთმანეთისგან განსხვავდება. 2 წლამდე ბიჭები გოგონებთან შედარებით სიმაღლეში უფრო სწრაფად იზრდებიან. გოგონები კი 2 წლის ასაკიდან, მთელი ბავშვობის განმავლობაში და მოზარდობის პერიოდამდე, ზრდის ამ ეტაპს ბიჭებზე ადრე გადიან. ეს განსხვავება ყველაზე მეტად 11-13 წლის ასაკში შეიმჩნევა და ამ პერიოდში გოგონები, როგორც წესი, ბიჭებზე მაღლები არიან. საშუალოდ 15-16 წლის ასაკში ეს განსხვავება ქრება, ხოლო მოზარდობის დასრულების შემდეგ ბიჭები გოგონებზე მაღლები ხდებიან. სიმაღლეში ზრდაზე მოქმედი ყველაზე მნიშვნელოვანი ფაქტორი გენეტიკაა. ამ ეტაპზე უკვე დაახლოებით განსაზღვრულია, რა სიმაღლეს მიაღწევს თქვენი ბავშვი ზრდასრულ ასაკში.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ძვლები მყარდება, მაგრამ... 🦴 ჩემი სხეულის ძვლები მყარდება, თუმცა თავის ქალის ძვლები ჯერ კიდევ არ არის შეზრდილი და რბილია. რატომ? იმიტომ, რომ დაბადებისას ვიწრო სამშობიარო არხში გასავლელად ჩემი თავი ოდნავ უნდა შეიკუმშოს და ფორმა შეიცვალოს. ეს ბუნების შესანიშნავი გეგმაა. დაბადების შემდეგ ჩემი თავის ფორმა კვლავ აღდგება.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'თუ ულტრაბგერითი გამოკვლევისას პლაცენტაზე, რომელიც მთელი ორსულობის განმავლობაში თქვენს ბავშვს საკვებ ნივთიერებებსა და ჟანგბადს აწვდის, ნათელი და თეთრი უბნები გამოჩნდა, ეს პლაცენტის კალციფიკაციის დაწყებაზე მიუთითებს.;;;
პლაცენტის დაბერება ორსულობის ნებისმიერ ეტაპზე შეიძლება მოხდეს, თუმცა ის ყველაზე ხშირად ბოლო ტრიმესტრში გვხვდება. ისეთი მავნე ჩვევები, როგორიცაა ალკოჰოლის მიღება და მოწევა, პლაცენტის დაბერებას აჩქარებს. ორსულობის ბოლო თვეებში პლაცენტის დაბერება, როგორც წესი, საშიში არ არის, თუმცა რეგულარულ მეთვალყურეობას საჭიროებს. ამასთან, თუ მაღალი არტერიული წნევა გაქვთ, სასურველია ექიმის მეთვალყურეობის ქვეშ იყოთ, რათა გაკონტროლდეს კალციფიკაციის გავლენის რისკი ბავშვზე.'), daily_tip_ka = COALESCE(daily_tip_ka, 'პრობიოტიკებით მდიდარი საკვები (ნატურალური იოგურტი, კეფირი) საჭმლის მომნელებელი სისტემის მოწესრიგებაში დაგეხმარებათ. შეკრულობის დროს შეიძლება სასარგებლო იყოს დილით ერთი კოვზი ზეითუნის ზეთის მიღება ან შავი ქლიავის ჩირის ჭამა.') WHERE id = 'ffcf32a2-fefd-4897-8f4a-507b427193a8';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ჭიპლარი, რომელიც თქვენსა და ბავშვს შორის დამაკავშირებელი რგოლის ფუნქციას ასრულებს და მის ყველა საჭიროებას უზრუნველყოფს, ორსულობის ამ ეტაპზე ზოგჯერ გარკვეულ პრობლემებს იწვევს. მათ შორისაა ჭიპლარის შემოხვევა და ორსისხლძარღვიანი ჭიპლარი. პლაცენტასა და თქვენი ბავშვის ჭიპს შორის დამაკავშირებელი ამ სტრუქტურის ბავშვის კისერზე შემოხვევამ შესაძლოა საფრთხე შექმნას.;;;
ჭიპლარი შეიძლება არა მხოლოდ ბავშვის კისერზე შემოეხვიოს, არამედ თავადაც გაინასკვოს. ზოგიერთი კვანძი მშობიარობის დროს წარმოიქმნება, ზოგი კი ორსულობის პერიოდში, ბავშვის მოძრაობების შედეგად. თუ კვანძი მოშვებულია, ის ბავშვს საფრთხეს არ უქმნის. თუმცა, თუ კვანძი მჭიდროა, შესაძლოა პლაცენტიდან ბავშვისკენ სისხლის მიმოქცევა შეიზღუდოს და ჟანგბადის ნაკლებობა გამოიწვიოს. ჭიპლარის შემოხვევის ყველაზე გავრცელებული ნიშანია ბოლო კვირებში ბავშვის მოძრაობების შემცირება. თუ კვანძი მშობიარობის დროს წარმოიქმნება, NST აპარატზე შესაძლოა გულისცემის დარღვევა გამოვლინდეს. ჭიპლარის თავისუფლად შემოხვევა უფრო ხშირად გვხვდება ჭარბი ამნიონური სითხის დროს, რადგან ბავშვს მოძრაობისთვის მეტი სივრცე აქვს. დაახლოებით 2000 მშობიარობიდან 1 შემთხვევაში ჭიპლარზე წარმოიქმნება იმდენად მჭიდრო კვანძი, რომ ბავშვისთვის რისკს ქმნის.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი წყალი იკლებს, მე კი ვიზრდები! 💧 ადრე ჩემი აუზი ძალიან ფართო იყო, მაგრამ ახლა იმდენ ადგილს ვიკავებ, რომ ამნიონური სითხის რაოდენობა შედარებით მცირე ჩანს. ახლა ჩემს მოძრაობებს უფრო მკაფიოდ და ძლიერად გრძნობ. როცა იდაყვს შენკენ მოვაწვები, შეიძლება შენს მუცელს ფორმაც კი შევუცვალო.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'ახლა, როდესაც ორსულობის დასასრულს უახლოვდებით, დროა დაფიქრდეთ, როგორ გსურთ მშობიარობა. წყალში მშობიარობა ბოლო წლებში მშობიარობის მეთოდებს შორის ერთ-ერთი ყველაზე აქტიურად შესწავლილი თემაა. ეს მეთოდი მშობიარობისთვის სპეციალურად მოწყობილ აუზში ან აბაზანაში ტარდება და მიზნად ისახავს წყლის დამამშვიდებელი ეფექტის გამოყენებას, რათა მშობიარობის ტკივილები უფრო მარტივად გადაიტანოთ. მშობიარობის დროს თბილ წყალში ყოფნა სხეულს ადუნებს და ჰორმონ ოქსიტოცინის გამოყოფას ზრდის. გამოყოფილი ოქსიტოცინი შეკუმშვებს უფრო რეგულარულს ხდის და მშობიარობის ხანგრძლივობას ამცირებს. თბილი წყალი ასევე არბილებს კუნთებსა და ქსოვილებს, რითაც ტკივილისა და დაძაბულობის შეგრძნებას ამცირებს. განსაკუთრებით მუცლისა და საზარდულის მიდამოში კუნთების მოდუნების შედეგად შეკუმშვების გადატანა ბევრად უფრო მარტივი ხდება. ამის წყალობით, შეგიძლიათ მშობიარობა უფრო მშვიდად და დადებითი ემოციებით დაასრულოთ.;;;
გარდა ამისა, თქვენი ბავშვი, რომელიც მთელი ორსულობის განმავლობაში ამნიონურ სითხეში ვითარდებოდა, თბილ წყალში დაბადებისას უფრო რბილ გადასვლას განიცდის, რის გამოც მშობიარობის ტრავმის ზემოქმედება მინიმუმამდე მცირდება.;;;
თუ წყალში მშობიარობა გსურთ, უნდა გადაამოწმოთ, აქვს თუ არა თქვენს საავადმყოფოს ამისთვის შესაბამისი პირობები.'), daily_tip_ka = COALESCE(daily_tip_ka, 'განაგრძეთ მუცელზე დამატენიანებელი ზეთების წასმა. მოერიდეთ მოფხანას. თუ გამონადენის ფერი ან სუნი შეიცვლება (გახდება მწვანე, ექნება უსიამოვნო სუნი), მიმართეთ ექიმს. ყოველდღიური საფენების გამოყენებამ შეიძლება მეტი კომფორტი მოგანიჭოთ.') WHERE id = '1071fbaa-eb8a-400f-b713-0a3f36f51bd7';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ქუთუთოების განცალკევების შემდეგ თქვენი ბავშვი სიფხიზლისას თვალებს უკვე საკმაოდ ხშირად ახელს. მეტიც, ფერადი გარსის დახმარებით მისი გუგები სინათლეზე შევიწროებას, ხოლო სიბნელეში გაფართოებას უკვე იწყებს.;;;
გუგა თვალის ფერადი ნაწილის — ფერადი გარსის — ცენტრში მდებარე ხვრელია. მისი საშუალებით სინათლე ბადურაზე ხვდება. ეს ნაწილი შავად გამოიყურება, რადგან მასში გამავალი სინათლის სხივები თვალის შიგნით არსებული ქსოვილების მიერ შთაინთქმება და გუგიდან უკან აღარ გამოდის. გუგის გარშემო მდებარე თვალის ფერადი ნაწილი ძირითადად გლუვი კუნთებისგან შედგება და შეკუმშვა შეუძლია. სინათლე თვალში გუგის გავლით შედის, ხოლო ფერადი გარსი, რომელიც გუგის ზომას აკონტროლებს, თვალში შემავალი სინათლის რაოდენობას არეგულირებს. გუგის გაფართოება და შევიწროება ფერად გარსში არსებული ორი გლუვი კუნთის დახმარებით ხდება. ძლიერი განათებისას ერთ-ერთი კუნთი მოდუნდება, რაც ფერადი გარსის გაფართოებასა და, შესაბამისად, გუგის შევიწროებას იწვევს და თვალს ინტენსიური სინათლის უარყოფითი ზემოქმედებისგან იცავს. ფერად გარსში მდებარე მეორე კუნთი კი სიბნელეში იკუმშება და ფერად გარსს კიდეებისკენ ქაჩავს. შედეგად, გუგა ფართოვდება, თვალში მეტი სინათლე შედის და სიბნელეში ხედვა ხდება შესაძლებელი.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი კანი გამჭვირვალე აღარ არის! 👶 ჩემი კანი გასქელდა, ვარდისფერი გახდა და შინაგანი ორგანოები აღარ ჩანს. ცხიმოვანი ფენა უფრო „ფუმფულას“ მხდის. უკვე ნამდვილ ახალშობილ ბავშვს ვგავარ. 3D ულტრაბგერით გამოკვლევაზე რომ დამინახავ, ჩემი ლოყების მოფერება მოგინდება!'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'თუ მეორე ორსულობა გაქვთ და პირველად საკეისრო კვეთით იმშობიარეთ, შეგიძლიათ SQSD განიხილოთ. SQSD საკეისრო კვეთის შემდეგ ბუნებრივი მშობიარობის შემოკლებული სახელწოდებაა. ეს გულისხმობს ბუნებრივი გზით მშობიარობას მას შემდეგ, რაც წინა მშობიარობა საკეისრო კვეთით ჩატარდა. ადრე ქალებს, რომლებმაც საკეისრო კვეთით იმშობიარეს, მომდევნო ორსულობის ბუნებრივი მშობიარობით დასრულებას არ ურჩევდნენ.;;;
თუმცა, ბოლო პერიოდში ჩატარებულმა კვლევებმა აჩვენა, რომ საკეისრო კვეთის შემდეგ ქალის მიერ მეორე ბავშვის ბუნებრივი გზით გაჩენის ალბათობა 75%-ზე მეტია.;;;
თუ საკეისრო კვეთიდან სულ მცირე 1 წელი გავიდა, ადრე არ გქონიათ საშვილოსნოს გახევა ან საშვილოსნოზე ჩატარებული სხვა ოპერაცია და ორსულობის განმავლობაში არ გამოვლენილა პრობლემა, რომელიც ბუნებრივ მშობიარობას ხელს შეუშლის, შეგიძლიათ SQSD მეთოდი განიხილოთ. ამასთან, ბუნებრივ მშობიარობას საკეისრო კვეთასთან შედარებით მეტი უპირატესობა აქვს. ბუნებრივი მშობიარობის შემდეგ ქალების აღდგენის პერიოდი უფრო ხანმოკლეა, ინფექციის რისკი მცირდება და სისხლის დანაკარგი მინიმალურია.'), daily_tip_ka = COALESCE(daily_tip_ka, 'დრო საკუთარ თავსაც დაუთმეთ. ეს მშობიარობამდე ბოლო კვირებია, როდესაც ჯერ კიდევ შეგიძლიათ განმარტოება. წაიკითხეთ წიგნი, უყურეთ ფილმს, შეხვდით მეგობრებს. დააფასეთ ეს მშვიდი დღეები.') WHERE id = '79fb5c0f-3cea-4126-92e7-e885b95bc603';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'გენები, რომლებიც თქვენი ბავშვის სიმაღლესა და წონას განსაზღვრავს, თქვენი სასქესო უჯრედების ქრომოსომებით გადაიცემა. განსაკუთრებით, სიმაღლეში ზრდის განმსაზღვრელი ფაქტორების 80% გენეტიკურ კოდებთანაა დაკავშირებული. ასეთი გენეტიკური კოდების რაოდენობა შესაძლოა 600-700-ს შორის მერყეობდეს. მოკლედ, თუ ბავშვის დედაც და მამაც გენეტიკურად დაბლები და გამხდრები არიან, სხვა ფაქტორების ზემოქმედების გარეშე ნაკლებად სავარაუდოა, რომ ბავშვი მაღალი გაიზარდოს ან წონის მატებისკენ იყოს მიდრეკილი. კვების ჩვევებიც პირდაპირ მოქმედებს წონის მატებაზე, ძვლების დაგრძელებასა და გამკვრივებაზე. ძვლების განვითარების ეს პროცესი სიმაღლეში ზრდას უზრუნველყოფს. სიმაღლისა და წონის თანაფარდობაზე, მემკვიდრეობით ფაქტორებთან ერთად, გავლენას ახდენს სხვადასხვა დაავადება, განვითარების შემაფერხებელი გენეტიკური დარღვევები, საკვები ნივთიერებების დეფიციტი და არასწორი კვების ჩვევები, ძილის რეჟიმი და ფიზიკური აქტივობა. სიმაღლეში ზრდასა და წონის მატებაზე კლიმატიც მოქმედებს. კერძოდ, ტროპიკული კლიმატის რეგიონებში მცხოვრები ადამიანები, როგორც წესი, უფრო დაბლები და მსხვილი აღნაგობისანი არიან, ხოლო ჩრდილოეთ ევროპაში, მათ შორის სკანდინავიის ქვეყნებში, ადამიანები უფრო მაღლები და გამხდრები არიან.'), baby_message_ka = COALESCE(baby_message_ka, 'თქვენს იმუნიტეტს ვიღებ! 🛡️ დედიკო, იცით, ახლა რას ვაკეთებ? თქვენი სისხლიდან ჩემთვის „იმუნიტეტის ჯარისკაცებს“ (ანტისხეულებს) ვაგროვებ. იმ დაავადებების წინააღმდეგ, რომელთა მიმართაც მთელი ცხოვრების განმავლობაში იმუნიტეტი გამოგიმუშავდათ, თქვენს ძალას მეც გადმომცემთ. როცა დავიბადები, მიკრობებისგან დამცავი ჩემი პირველი ფარი თქვენ იქნებით.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'ორსულობის პერიოდში, თქვენი ბავშვის ძვლების განვითარების გამო, D ვიტამინის საჭიროება დაახლოებით 5-ჯერ იზრდება. განსაკუთრებით მეორე ტრიმესტრში, როდესაც ბავშვის ძვლების განვითარება ჩქარდება, თქვენი ორგანიზმიდან ბავშვზე დიდი რაოდენობით კალციუმი გადადის. ამიტომ, D ვიტამინზე გაზრდილი მოთხოვნილების დასაკმაყოფილებლად, თქვენი ორგანიზმი ნაწლავებში ამ ვიტამინის შეწოვას აძლიერებს. ამავდროულად, D ვიტამინი ძვლებიდან სისხლში გადადის. ამის გამო ორსულობის განმავლობაში თქვენი ძვლები შეიძლება უფრო მყიფე გახდეს.;;;
ორსულობის განმავლობაში ქალები ძვლოვანი მასის დაახლოებით 5%-ს კარგავენ. ორგანიზმში D ვიტამინის დონის შემცირების შედეგად შეიძლება გაიზარდოს გესტაციური დიაბეტის, პრეეკლამფსიისა და ინფექციებით დაავადების რისკი. ამიტომ D ვიტამინის დანამატის მიღება ძალიან მნიშვნელოვანია. დანამატებთან ერთად, სასარგებლოა დღის განმავლობაში 15-20 წუთით მზის სხივების ზემოქმედებაც.'), daily_tip_ka = COALESCE(daily_tip_ka, 'განაგრძეთ ბევრი წყლის სმა. ეს მნიშვნელოვანია სხეულის ტემპერატურის დასარეგულირებლად და გაუწყლოების თავიდან ასაცილებლად. გაუწყლოებამ შესაძლოა ნაადრევი შეკუმშვები გამოიწვიოს.') WHERE id = 'adc2549c-64e5-4fcb-ab22-00fd00f59fac';
UPDATE public.pregnancy_daily_content SET baby_development_ka = COALESCE(baby_development_ka, 'ჭიპლარი, რომელიც თქვენი ბავშვის პლაცენტასა და ორგანიზმს შორის საკვებ ნივთიერებებსა და ჟანგბადს გადააქვს, 2 არტერიისა და 1 ვენისგან შედგება. ჭიპლარი, რომელსაც სამედიცინო ენაზე უმბილიკალურ კორდს უწოდებენ, ფიზიოლოგიურად და გენეტიკურად თქვენი ბავშვის ნაწილია. ის ჟანგბადითა და საკვები ნივთიერებებით მდიდარ სისხლსა და ნარჩენი ნივთიერებების შემცველ სისხლს ერთმანეთში შერევის გარეშე გადააქვს. ჭიპლარის სიგრძე დაახლოებით 50 სმ-ია, ხოლო დიამეტრი — 2 სმ. ამ სტრუქტურაში არსებული არტერიები და ვენა საპირისპირო ფუნქციას ასრულებს. ჩვეულებრივ, ჟანგბადით მდიდარი სისხლი არტერიებით გადაადგილდება, ხოლო ჟანგბადით ღარიბი და ნარჩენი ნივთიერებების შემცველი სისხლი — ვენებით. ჭიპლარში კი არტერიებს ნარჩენი ნივთიერებების შემცველი სისხლი გადააქვს, ხოლო ვენას — ჟანგბადითა და საკვები ნივთიერებებით მდიდარი სისხლი. რადგან ჭიპლარი ნერვებს არ შეიცავს, მშობიარობის შემდეგ მისი გადაჭრა ბავშვს ტკივილს არ აყენებს. თუმცა ზოგ შემთხვევაში ჭიპლარი შეიძლება მხოლოდ ორი სისხლძარღვისგან — ერთი არტერიისა და ერთი ვენისგან — შედგებოდეს. ასეთ შემთხვევებში ბავშვის განვითარებას ამოწმებენ და შესაძლოა უფრო ხშირი მეთვალყურეობა გახდეს საჭირო.'), baby_message_ka = COALESCE(baby_message_ka, 'ჩემი ძვლები ქვასავით მაგარია! 🦴 ჩემი ჩონჩხი მთლიანად გამაგრდა. ხელები და ფეხები რეზინასავით რბილი აღარ არის — უკვე მტკიცეა. როცა ფეხს გირტყამთ, ალბათ ამას უფრო მტკივნეულად გრძნობთ. განაგრძეთ კალციუმის მიღება, რადგან მე ჯერ კიდევ თქვენს მარაგს ვიყენებ.'), baby_size_fruit_ka = COALESCE(baby_size_fruit_ka, 'ანანასი'), body_changes_ka = COALESCE(body_changes_ka, 'რელაქსინი ცილოვანი ჰორმონია, რომლის დონეც თქვენს ორგანიზმში ორსულობის დაწყებისთანავე იმატებს.;;;
