UPDATE public.safety_items SET name_ka = COALESCE(name_ka, 'ავიამგზავრობა'), description_ka = COALESCE(description_ka, 'კომერციული ავიაკომპანიებით მგზავრობა ორსულობის პერიოდში, ზოგადად, უსაფრთხოდ მიიჩნევა. თუმცა, განსაკუთრებით ხანგრძლივი ფრენის წინ, რეკომენდებულია ექიმთან კონსულტაცია, მაშინაც კი, თუ ორსულობასთან დაკავშირებული პრობლემა არ გაქვთ. დალიეთ ბევრი წყალი, იმოძრავეთ თრომბის წარმოქმნის თავიდან ასაცილებლად და, თუ რეკომენდებულია, გამოიყენეთ კომპრესიული წინდები. ეს რეკომენდაციები მეძუძური დედებისთვისაც მოქმედებს, თუმცა ხანგრძლივი ფრენისას სასარგებლოა ბავშვის კვებისა და კომფორტისთვის დამატებით მომზადება.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
UPDATE public.safety_items SET name_ka = COALESCE(name_ka, 'ორაგული (სიომგა)'), description_ka = COALESCE(description_ka, 'ომეგა-3-ის წყაროა. რეკომენდებულია კვირაში მაქსიმუმ 2-ჯერ, სრულად მომზადებული სახით.') WHERE id = 'b0c7bfda-4110-4f88-8a68-a6303d1447c6';
UPDATE public.safety_items SET name_ka = COALESCE(name_ka, 'თვითმფრინავით მგზავრობა'), description_ka = COALESCE(description_ka, 'კომერციული რეისებით მგზავრობა ორსულობის პერიოდში, ზოგადად, უსაფრთხოდ მიიჩნევა. რეკომენდებულია ექიმთან კონსულტაცია თვითმფრინავით მგზავრობის შესახებ, განსაკუთრებით მესამე ტრიმესტრში, ასევე ბევრი წყლის დალევა და მოძრაობა თრომბის წარმოქმნის თავიდან ასაცილებლად. ეს რეკომენდაციები მეძუძური დედებისთვისაც მოქმედებს, თუმცა ხანგრძლივი ფრენისას საჭიროა დამატებითი მომზადება ბავშვის კვებისა და კომფორტისთვის.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
UPDATE public.safety_items SET name_ka = COALESCE(name_ka, 'სუჯუკი'), description_ka = COALESCE(description_ka, 'ძუძუთი კვების პერიოდში სუჯუკის ზომიერი რაოდენობით მიღება, ზოგადად, უსაფრთხოა, თუმცა მნიშვნელოვანია ნატრიუმისა და ცხიმის მაღალი შემცველობის გათვალისწინება. ამასთან, ცხარე საკვებმა ზოგჯერ დედის რძის მეშვეობით შეიძლება გავლენა მოახდინოს ბავშვზე და გამოიწვიოს დისკომფორტი ან საჭმლის მონელების პრობლემები. დააკვირდით თქვენი ბავშვის რეაქციას.') WHERE id = 'b4267eb3-6e6a-46f3-93ce-1dab05fea063';
